import { supabase } from '@/lib/supabase';
import type { Activity, Contribution, ContributionFile, Feedback, Notification, Profile, Role, StudyNote, Subject, Syllabus } from '@/types';
import { Activity as ActivityIcon, ArrowLeft, Bell, BookOpen, Check, ChevronRight, CircleUserRound, ClipboardCopy, Cloud, Code2, Eye, EyeOff, FileText, Github, GraduationCap, LayoutDashboard, Link as LinkIcon, ListChecks, LogOut, Mail, Megaphone, Menu, Moon, Pencil, PencilLine, Plus, Search, Send, Settings, ShieldCheck, Sparkles, Star, Sun, Trash2, Trophy, Upload, Users, X, Zap } from 'lucide-react';

const cn = (...classes: Array<string | false | null | undefined>): string => classes.filter(Boolean).join(' ');
const formatDate = (date: string): string => new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${date}T00:00:00`));
const today = (): string => new Date().toISOString().slice(0, 10);
const friendlyError = (): string => 'Something went wrong. Please try again.';
// Time-aware greeting so it says the right thing all day, with a sun/moon icon.
function greetingInfo(): { text: string; Icon: typeof Sun } { const h = new Date().getHours(); return h < 12 ? { text: 'Good morning', Icon: Sun } : h < 17 ? { text: 'Good afternoon', Icon: Sun } : h < 21 ? { text: 'Good evening', Icon: Moon } : { text: 'Good night', Icon: Moon }; }
// Day/night theme: persisted per browser, applied as a class on <html>.
function useTheme(): [boolean, () => void] {
  const [night, setNight] = useState<boolean>(() => { try { return localStorage.getItem('fsd_theme') === 'night'; } catch { return false; } });
  useEffect(() => {
    document.documentElement.classList.toggle('night', night);
    try { localStorage.setItem('fsd_theme', night ? 'night' : 'day'); } catch { /* ignore */ }
  }, [night]);
  return [night, () => setNight((n) => !n)];
}
// Keeps dashboards live: refetch every 8s and whenever the tab regains focus.
// This is what makes the approval workflow feel direct — a student submission
// lands in the admin queue without anyone refreshing, and an approval shows up
// on the student dashboard the same way.
function useLiveRefresh(refetch: () => void, intervalMs = 8000): void {
  useEffect(() => {
    const timer = setInterval(refetch, intervalMs);
    const onFocus = (): void => { if (document.visibilityState === 'visible') refetch(); };
    // Fresh data must win the moment connectivity returns.
    const onBackOnline = (): void => { if (!(window as unknown as { __fsdOffline?: boolean }).__fsdOffline) refetch(); };
    window.addEventListener('fsd-connectivity', onBackOnline as EventListener);
    window.addEventListener('online', onBackOnline);
    document.addEventListener('visibilitychange', onFocus);
    return () => { clearInterval(timer); window.removeEventListener('fsd-connectivity', onBackOnline as EventListener); window.removeEventListener('online', onBackOnline); document.removeEventListener('visibilitychange', onFocus); };
  });
}
const authErrorMessage = (error: { message?: string; code?: string }): string => {
  const message = (error.message || '').toLowerCase();
  if (error.code === 'user_already_exists' || message.includes('already registered') || message.includes('already been registered')) return 'An account with this email already exists. Switch to sign in instead.';
  if (message.includes('invalid email')) return 'Enter a valid email address.';
  if (message.includes('password')) {
    const minimum = message.match(/at least (\\d+) characters/);
    if (minimum) return `Use a password with at least ${minimum[1]} characters.`;
    if (message.includes('compromised') || message.includes('breached') || message.includes('common')) return 'Choose a less common password for better account security.';
    return 'Choose a stronger password and try again.';
  }
  if (message.includes('rate limit')) return 'Too many attempts. Please wait a moment and try again.';
  if (message.includes('username') || message.includes('profiles_username')) return 'That username is already in use. Choose another one.';
  return 'We could not create that account right now. Please try again.';
};

function App() {
  const [session, setSession] = useState<{ userId: string } | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);
  const [route, setRoute] = useState(new URL(window.location.href).pathname);

  useEffect(() => {
    const loadSession = async (): Promise<void> => {
      const { data } = await supabase.auth.getSession();
      if (data.session) { setSession({ userId: data.session.user.id }); await loadProfile(data.session.user.id); }
      setLoading(false);
    };
    const loadProfile = async (id: string): Promise<void> => {
      const { data } = await supabase.from('profiles').select('*').eq('id', id).maybeSingle();
      if (data) setProfile(data as Profile);
      else {
        // Stale session pointing at a deleted account — drop it so the user
        // reaches the sign-in screen instead of an endless loading spinner.
        await supabase.auth.signOut();
        setSession(null); setProfile(null);
      }
    };
    void loadSession();
    const { data: listener } = supabase.auth.onAuthStateChange((_event, nextSession) => {
      (async () => {
        if (nextSession) { setSession({ userId: nextSession.user.id }); await loadProfile(nextSession.user.id); }
        else { setSession(null); setProfile(null); }
        setLoading(false);
      })();
    });
    const onPop = (): void => setRoute(new URL(window.location.href).pathname);
    window.addEventListener('popstate', onPop);
    return () => { listener.subscription.unsubscribe(); window.removeEventListener('popstate', onPop); };
  }, []);

  // Route state tracks the pathname only — query strings (e.g. ?subject=Frontend)
  // must not leak into route matching, or every route falls through to "Page not found".
  const navigate = (path: string): void => { window.history.pushState({}, '', path); setRoute(new URL(path, window.location.origin).pathname); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  const signOut = async (): Promise<void> => { await supabase.auth.signOut(); navigate('/login'); };
  // Live notification popups: poll for unread items, toast in-app, and raise a
  // real OS notification when the app is installed or running in background.
  const [toasts, setToasts] = useState<Notification[]>([]);
  const [notifAsk, setNotifAsk] = useState(false);
  const [offline, setOfflineState] = useState(!navigator.onLine);
  useEffect(() => {
    const w = window as unknown as { __fsdOffline?: boolean };
    const onConn = (e: Event): void => { const v = !!(e as CustomEvent).detail?.offline; w.__fsdOffline = v; setOfflineState(v); };
    const onOnline = (): void => { w.__fsdOffline = false; setOfflineState(false); };
    const onOfflineEvt = (): void => { w.__fsdOffline = true; setOfflineState(true); };
    w.__fsdOffline = !navigator.onLine;
    window.addEventListener('fsd-connectivity', onConn as EventListener);
    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOfflineEvt);
    return () => { window.removeEventListener('fsd-connectivity', onConn as EventListener); window.removeEventListener('online', onOnline); window.removeEventListener('offline', onOfflineEvt); };
  }, []);
  const seenRef = useRef<Set<string>>(new Set());
  const primedRef = useRef(false);
  useEffect(() => {
    if (!profile) return;
    const showOne = async (n: Notification): Promise<void> => {
      setToasts((t) => [...t.filter((x) => x.id !== n.id), n]);
      setTimeout(() => setToasts((t) => t.filter((x) => x.id !== n.id)), 7000);
      try {
        if ('Notification' in window && window.Notification.permission === 'granted' && (document.hidden || window.matchMedia('(display-mode: standalone)').matches)) {
          const reg = await navigator.serviceWorker?.getRegistration();
          const opts: NotificationOptions = { body: n.message, icon: '/icon-192.png?v=2', badge: '/icon-192.png?v=2', tag: n.id, data: { url: '/notifications' } };
          if (reg) await reg.showNotification(n.title, opts); else new window.Notification(n.title, opts);
        }
      } catch { /* notifications unavailable */ }
    };
    const poll = async (): Promise<void> => {
      const { data } = await supabase.from('notifications').select('*').eq('user_id', profile.id).eq('read', false).order('created_at', { ascending: false }).limit(5);
      const rows = (data || []) as Notification[];
      // First poll only primes the seen-set (no popups for pre-existing mail);
      // everything arriving after that pops for real.
      if (!primedRef.current) { for (const r of rows) seenRef.current.add(r.id); primedRef.current = true; return; }
      const fresh = rows.filter((n) => !seenRef.current.has(n.id));
      for (const n of fresh) { seenRef.current.add(n.id); void showOne(n); }
    };
    void poll();
    const iv = setInterval(() => { void poll(); }, 10000);
    return () => clearInterval(iv);
  }, [profile?.id]);
  useEffect(() => { try { if (!localStorage.getItem('fsd_notif_asked') && 'Notification' in window && window.Notification.permission === 'default') setNotifAsk(true); } catch { /* ignore */ } }, []);
  const enableNotifs = async (): Promise<void> => { try { if ('Notification' in window) await window.Notification.requestPermission(); } catch { /* ignore */ } setNotifAsk(false); try { localStorage.setItem('fsd_notif_asked', '1'); } catch { /* ignore */ } };
  const openToast = async (n: Notification): Promise<void> => { setToasts((t) => t.filter((x) => x.id !== n.id)); await supabase.from('notifications').update({ read: true }).eq('id', n.id); navigate('/notifications'); };
  if (loading) return <LoadingScreen />;
  if (route === '/reset-password') return <PasswordResetScreen />;
  if (!session) return route === '/admin/login' ? <AuthScreen admin /> : <AuthScreen />;
  if (!profile) return <LoadingScreen />;
  if (route === '/login' || route === '/admin/login') { navigate(profile.role === 'admin' ? '/admin' : profile.role === 'teacher' ? '/teacher' : '/dashboard'); return null; }
  if (route.startsWith('/admin') && !route.startsWith('/admin-notes') && profile.role !== 'admin') return <DeniedScreen navigate={navigate} />;
  if (route === '/teacher' && profile.role !== 'teacher' && profile.role !== 'admin') return <DeniedScreen navigate={navigate} />;
  return <><AppShell profile={profile} route={route} navigate={navigate} signOut={signOut} />{offline && <div className="fixed bottom-4 left-4 z-[60] flex items-center gap-2 rounded-full bg-[#fff7df] px-4 py-2 text-xs font-bold text-[#7a5b0d] shadow-lg"><span className="h-2 w-2 animate-pulse rounded-full bg-[#d9a514]" />Offline — showing your saved data. New changes can't be saved right now.</div>}{toasts.length > 0 && <div className="fixed right-4 top-4 z-[60] w-80 max-w-[calc(100vw-2rem)] space-y-2">{toasts.map((n) => <button key={n.id} onClick={() => void openToast(n)} className="card w-full p-4 text-left shadow-lg transition hover:border-[#9ad7c5]"><p className="text-sm font-bold">{n.title}</p>{n.sender_name && <p className="mt-0.5 flex flex-wrap items-center gap-1.5 text-xs text-[#6c8589]"><span className="font-semibold">From {n.sender_name}</span><RoleBadge role={n.sender_role} /></p>}<p className="mt-1 line-clamp-2 text-sm leading-5 text-[#6c8589]">{n.message}</p></button>)}</div>}{notifAsk && <div className="fixed bottom-4 left-1/2 z-[60] w-[calc(100vw-2rem)] max-w-sm -translate-x-1/2 rounded-xl border border-[#b8e6d0] bg-white px-4 py-3 shadow-lg"><p className="text-sm font-semibold">Get popups for new messages and approvals?</p><div className="mt-2 flex items-center gap-3"><button className="btn-primary px-3 py-1.5 text-xs" onClick={() => void enableNotifs()}>Enable notifications</button><button className="text-xs font-semibold text-[#6c8589]" onClick={() => { setNotifAsk(false); try { localStorage.setItem('fsd_notif_asked', '1'); } catch { /* ignore */ } }}>Not now</button></div></div>}</>;
}

function LoadingScreen(): JSX.Element { return <div className="flex min-h-screen items-center justify-center bg-[#061c2c]"><div className="text-center text-white"><div className="mx-auto mb-4 h-10 w-10 animate-spin rounded-full border-2 border-white/20 border-t-[#7de0c0]" /><p className="text-sm text-white/70">Loading your workspace</p></div></div>; }
function DeniedScreen({ navigate }: { navigate: (path: string) => void }): JSX.Element { return <div className="flex min-h-screen items-center justify-center bg-[#061c2c] p-6"><div className="card max-w-md p-8 text-center"><ShieldCheck className="mx-auto mb-5 h-12 w-12 text-[#087f78]" /><h1 className="text-2xl font-bold text-[#102a3a]">Access restricted</h1><p className="mt-3 text-sm leading-6 text-[#61777c]">This area is reserved for another role in the platform.</p><button className="btn-primary mt-6" onClick={() => navigate('/dashboard')}>Return to dashboard</button></div></div>; }

// Role identity: a matching icon + tinted badge for every reviewer or sender.
const roleStyles: Record<string, { badge: string; icon: typeof ShieldCheck }> = {
  admin: { badge: 'bg-[#ede9fe] text-[#6d5ae0]', icon: ShieldCheck },
  teacher: { badge: 'bg-[#fff7df] text-[#a47816]', icon: BookOpen },
  student: { badge: 'bg-[#e7f7f1] text-[#087f78]', icon: GraduationCap },
};
function RoleBadge({ role }: { role?: string | null }): JSX.Element | null {
  if (!role) return null;
  const s = roleStyles[role] || roleStyles.student;
  const Icon = s.icon;
  return <span className={cn('inline-flex shrink-0 items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide', s.badge)}><Icon className="h-3 w-3" />{role}</span>;
}

// Password input with a show/hide eye toggle, used on every auth screen.
function PasswordField(props: { value: string; onChange: (v: string) => void; placeholder: string; minLength?: number; hint?: string }): JSX.Element {
  const [visible, setVisible] = useState(false);
  return <div>
    <div className="relative">
      <input className="field pr-12" type={visible ? 'text' : 'password'} minLength={props.minLength} placeholder={props.placeholder} value={props.value} onChange={(e) => props.onChange(e.target.value)} />
      <button type="button" title={visible ? 'Hide password' : 'Show password'} aria-label={visible ? 'Hide password' : 'Show password'} onClick={() => setVisible(!visible)} className="absolute right-2 top-1/2 -translate-y-1/2 rounded-lg p-2 text-[#8ca1a3] transition hover:bg-[#f0faf7] hover:text-[#087f78]">{visible ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
    </div>
    {props.hint && <p className="mt-2 text-xs text-[#7b9295]">{props.hint}</p>}
  </div>;
}

function PasswordResetScreen(): JSX.Element {
  const params = new URLSearchParams(window.location.search);
  const [email, setEmail] = useState(params.get('email') || '');
  const [token] = useState(params.get('token') || '');
  const [password, setPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [resetLink, setResetLink] = useState('');
  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    setError('');
    setMessage('');
    if (!token) {
      if (!email) { setError('Enter the email on your account.'); return; }
      setBusy(true);
      const { data, error: requestError } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/reset-password` });
      setBusy(false);
      if (requestError) { setError(requestError.message || 'We could not prepare a reset link. Please try again.'); return; }
      setResetLink(`${window.location.origin}/reset-password?email=${encodeURIComponent(email)}&token=${data?.code ?? ''}`);
      return;
    }
    if (password.length < 6) { setError('Use a password with at least 6 characters.'); return; }
    if (password !== confirmation) { setError('The passwords do not match.'); return; }
    setBusy(true);
    const { error: resetError } = await supabase.auth.resetPassword({ email, token, password });
    setBusy(false);
    if (resetError) setError(resetError.message || 'We could not update your password. Please request a new reset link.');
    else setMessage('Your password has been updated. You can sign in with it now.');
  };
  return <div className="flex min-h-screen items-center justify-center bg-[#f4f8f7] px-6 py-12"><div className="w-full max-w-md"><div className="mb-8"><p className="eyebrow">Account security</p><h1 className="mt-2 text-3xl font-bold text-[#102a3a]">{token ? 'Create a new password' : 'Reset your password'}</h1><p className="mt-3 text-sm leading-6 text-[#61777c]">{token ? 'Choose a new password for your FullstackDev account.' : 'Enter your account email and we will prepare a secure reset link for you.'}</p></div>{error && <div className="mb-5 rounded-xl border border-[#f3c7c7] bg-[#fff4f4] px-4 py-3 text-sm text-[#a33b3b]">{error}</div>}{message && <div className="mb-5 rounded-xl border border-[#b8e6d0] bg-[#effbf5] px-4 py-3 text-sm text-[#176345]">{message}<button className="mt-3 block font-bold text-[#087f78] hover:underline" onClick={() => { window.history.pushState({}, '', '/login'); window.location.reload(); }}>Return to sign in</button></div>}{resetLink && !token && <div className="mb-5 rounded-xl border border-[#b8e6d0] bg-[#effbf5] px-4 py-3 text-sm text-[#176345]"><Mail className="mb-1 h-4 w-4" />Your secure reset link is ready. <a className="font-bold underline" href={resetLink}>Click here to set a new password</a>.</div>}{token ? <form onSubmit={submit} className="card space-y-4 p-6"><PasswordField value={password} onChange={setPassword} placeholder="New password" minLength={6} hint="Use at least 6 characters." /><PasswordField value={confirmation} onChange={setConfirmation} placeholder="Confirm new password" minLength={6} /><button className="btn-primary w-full py-3.5" disabled={busy || Boolean(message)}>{busy ? 'Updating…' : 'Update password'}<ChevronRight className="h-4 w-4" /></button></form> : <form onSubmit={submit} className="card space-y-4 p-6"><input className="field" type="email" placeholder="Your account email" value={email} onChange={(event) => setEmail(event.target.value)} /><button className="btn-primary w-full py-3.5" disabled={busy || Boolean(resetLink)}>{busy ? 'Preparing…' : 'Send reset link'}<ChevronRight className="h-4 w-4" /></button></form>}</div></div>;
}

function AuthScreen({ admin = false }: { admin?: boolean }): JSX.Element {
  const [mode, setMode] = useState<'login' | 'signup'>('login');
  const [role, setRole] = useState<'student' | 'teacher'>('student');
  const [values, setValues] = useState({ email: '', password: '', fullName: '', username: '' });
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const [showForgot, setShowForgot] = useState(false); const [resetUrl, setResetUrl] = useState('');
  const sendReset = async (): Promise<void> => {
    setBusy(true); setError(''); setResetUrl('');
    const { data, error: resetError } = await supabase.auth.resetPasswordForEmail(values.email, { redirectTo: `${window.location.origin}/reset-password` });
    setBusy(false);
    if (resetError) { setError(resetError.message || 'We could not prepare a reset link. Check the email and try again.'); return; }
    setResetUrl(`${window.location.origin}/reset-password?email=${encodeURIComponent(values.email)}&token=${data?.code ?? ''}`);
  };
  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault(); setBusy(true); setError('');
    if (!values.email || values.password.length < 6 || (mode === 'signup' && !values.fullName)) { setError('Please complete every required field. Passwords must be at least 6 characters.'); setBusy(false); return; }
    const result = mode === 'signup' ? await supabase.auth.signUp({ email: values.email, password: values.password, options: { data: { full_name: values.fullName, username: values.username, role } } }) : await supabase.auth.signInWithPassword({ email: values.email, password: values.password });
    if (result.error) { setError(mode === 'login' ? 'The email or password is not correct.' : authErrorMessage(result.error)); setBusy(false); return; }
    if (mode === 'signup') { setMode('login'); setError('Account created. You can now sign in.'); setBusy(false); return; }
    const userId = result.data.user?.id;
    if (!userId) { setError('We could not start your session.'); setBusy(false); return; }
    const { data: foundProfile } = await supabase.from('profiles').select('role').eq('id', userId).maybeSingle();
    const expected: Role = admin ? 'admin' : role;
    if (!foundProfile || foundProfile.role !== expected) { await supabase.auth.signOut(); setError(`This account is not registered as a ${expected}.`); setBusy(false); return; }
    window.location.href = admin ? '/admin' : role === 'teacher' ? '/teacher' : '/dashboard';
  };
  return <div className="grid min-h-screen lg:grid-cols-[0.9fr_1.1fr]">
    <div className="relative hidden overflow-hidden bg-[#061c2c] p-12 text-white lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-40 -top-40 h-96 w-96 rounded-full bg-[#087f78]/30 blur-3xl" /><div className="relative"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#8de6c5] p-2 text-[#062b37]"><Code2 className="h-5 w-5" /></div><span className="font-bold tracking-tight">Fullstack<span className="text-[#8de6c5]">Dev</span></span></div><div className="mt-32 max-w-md"><p className="eyebrow text-[#8de6c5]">Build. Share. Grow.</p><h1 className="mt-5 text-5xl font-bold leading-[1.08]">Your progress,<br /><span className="text-[#8de6c5]">made visible.</span></h1><p className="mt-6 max-w-sm text-base leading-7 text-white/60">A focused home for developers to turn daily learning into a portfolio of meaningful work.</p></div></div><div className="relative flex items-center gap-3 text-sm text-white/50"><Sparkles className="h-4 w-4 text-[#8de6c5]" /> Ship real work, get real feedback, grow in the open.</div></div>
    <div className="flex items-center justify-center bg-[#f4f8f7] px-6 py-12"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#087f78] p-2 text-white"><Code2 className="h-5 w-5" /></div><span className="font-bold">Fullstack<span className="text-[#087f78]">Dev</span></span></div></div><div className="mb-8"><p className="eyebrow">{admin ? 'Admin portal' : 'Welcome back'}</p><h2 className="mt-2 text-3xl font-bold text-[#102a3a]">{mode === 'login' ? 'Sign in to your workspace' : 'Create your account'}</h2><p className="mt-2 text-sm text-[#61777c]">{admin ? 'Secure access for platform administrators.' : 'Keep your learning momentum moving forward.'}</p></div>{!admin && <div className="mb-6 grid grid-cols-2 gap-2 rounded-xl bg-[#e4f0ed] p-1"><button className={cn('rounded-lg px-3 py-2 text-sm font-semibold transition', role === 'student' ? 'bg-white text-[#087f78] shadow-sm' : 'text-[#61777c]')} onClick={() => setRole('student')}>Student</button><button className={cn('rounded-lg px-3 py-2 text-sm font-semibold transition', role === 'teacher' ? 'bg-white text-[#087f78] shadow-sm' : 'text-[#61777c]')} onClick={() => setRole('teacher')}>Teacher</button></div>}{error && <div className={cn('mb-5 rounded-xl border px-4 py-3 text-sm', error.startsWith('Account') ? 'border-[#b8e6d0] bg-[#effbf5] text-[#176345]' : 'border-[#f3c7c7] bg-[#fff4f4] text-[#a33b3b]')}>{error}</div>}<form onSubmit={submit} className="space-y-4">{mode === 'signup' && <><input className="field" placeholder="Full name" value={values.fullName} onChange={(e) => setValues({ ...values, fullName: e.target.value })} /><input className="field" placeholder="Username (optional)" value={values.username} onChange={(e) => setValues({ ...values, username: e.target.value })} /></>}<input className="field" type="email" placeholder="Email address" value={values.email} onChange={(e) => setValues({ ...values, email: e.target.value })} /><PasswordField value={values.password} onChange={(password) => setValues({ ...values, password })} placeholder="Password" minLength={6} hint={mode === 'signup' ? 'Use at least 6 characters.' : undefined} /><button className="btn-primary w-full py-3.5" disabled={busy}>{busy ? 'Please wait…' : mode === 'login' ? 'Sign in' : 'Create account'}<ChevronRight className="h-4 w-4" /></button>{mode === 'login' && (showForgot ? (resetUrl ? <div className="mt-4 rounded-xl border border-[#b8e6d0] bg-[#effbf5] px-4 py-3 text-sm text-[#176345]"><Mail className="mb-1 h-4 w-4" />Reset link ready for <b>{values.email}</b>. <a className="font-bold underline" href={resetUrl}>Click here to set a new password</a>.<button type="button" className="mt-2 block font-semibold text-[#087f78] hover:underline" onClick={() => { setShowForgot(false); setResetUrl(''); }}>Back to sign in</button></div> : <div className="mt-4 space-y-3 rounded-xl border border-[#e5efec] bg-[#f6fcf9] p-4"><p className="text-sm font-semibold text-[#185464]">Reset your password</p><p className="text-xs text-[#6c8589]">Enter your account email and we will prepare a secure reset link for you.</p><input className="field" type="email" placeholder="Your account email" value={values.email} onChange={(e) => setValues({ ...values, email: e.target.value })} /><button type="button" className="btn-primary w-full" disabled={busy || !values.email} onClick={() => void sendReset()}>{busy ? 'Preparing…' : 'Send reset link'}</button><button type="button" className="w-full text-center text-xs font-semibold text-[#6c8589] hover:underline" onClick={() => setShowForgot(false)}>Back to sign in</button></div>) : <button type="button" className="mt-4 w-full text-center text-sm text-[#087f78] hover:underline" onClick={() => { setShowForgot(true); setResetUrl(''); setError(''); }}>Forgot your password?</button>)}</form>{!admin && <button className="mt-6 w-full text-center text-sm font-semibold text-[#087f78] hover:underline" onClick={() => { setMode(mode === 'login' ? 'signup' : 'login'); setError(''); setShowForgot(false); setResetUrl(''); }}>{mode === 'login' ? 'New here? Create an account' : 'Already have an account? Sign in'}</button>}{!admin && mode === 'login' && <a href="/admin/login" className="mt-3 flex items-center justify-center gap-1.5 text-center text-xs font-semibold text-[#6c8589] hover:text-[#087f78]"><ShieldCheck className="h-3.5 w-3.5" />Admin sign in</a>}</div></div></div>;
}

interface ShellProps { profile: Profile; route: string; navigate: (path: string) => void; signOut: () => Promise<void>; }function AppShell({ profile, route, navigate, signOut }: ShellProps): JSX.Element { const [mobileOpen, setMobileOpen] = useState(false); const [night, toggleTheme] = useTheme();
  const navItems = profile.role === 'admin' ? [{ path: '/admin', label: 'Admin overview', icon: ShieldCheck }, { path: '/students', label: 'Users', icon: Users }, { path: '/learning-path', label: 'Learning notes', icon: BookOpen }, { path: '/notifications', label: 'Notifications', icon: Bell }, { path: '/settings', label: 'Settings', icon: Settings }] : profile.role === 'teacher' ? [{ path: '/teacher', label: 'Overview', icon: LayoutDashboard }, { path: '/contributions', label: 'My contributions', icon: Code2 }, { path: '/students', label: 'Students', icon: Users }, { path: '/learning-path', label: 'Learning notes', icon: BookOpen }, { path: '/notifications', label: 'Notifications', icon: Bell }, { path: '/profile', label: 'Profile', icon: CircleUserRound }, { path: '/settings', label: 'Settings', icon: Settings }] : [{ path: '/dashboard', label: 'Overview', icon: LayoutDashboard }, { path: '/contributions', label: 'Contributions', icon: Code2 }, { path: '/progress', label: 'Progress', icon: Trophy }, { path: '/learning-path', label: 'Learning path', icon: BookOpen }, { path: '/students', label: 'Students', icon: Users }, { path: '/notifications', label: 'Notifications', icon: Bell }, { path: '/profile', label: 'Profile', icon: CircleUserRound }, { path: '/settings', label: 'Settings', icon: Settings }];
  const content = route === '/dashboard' || route === '/' ? <Dashboard profile={profile} navigate={navigate} /> : route === '/contributions' ? <Contributions profile={profile} navigate={navigate} /> : route === '/contributions/new' ? <ContributionForm profile={profile} navigate={navigate} /> : route.match(/^\/contributions\/[^/]+\/edit$/) ? <ContributionForm profile={profile} navigate={navigate} contributionId={route.split('/')[2]} /> : route.startsWith('/contributions/') ? <ContributionDetail profile={profile} navigate={navigate} contributionId={route.split('/')[2]} /> : route === '/progress' ? <Progress profile={profile} /> : route === '/learning-path' ? <LearningPath profile={profile} navigate={navigate} /> : route === '/students' ? <Students navigate={navigate} /> : route.startsWith('/students/') ? <StudentDetail navigate={navigate} studentId={route.split('/')[2]} /> : route.startsWith('/admin-notes/') ? <AdminNoteDetail navigate={navigate} noteId={route.split('/')[2]} profile={profile} /> : route === '/notifications' ? <Notifications profile={profile} /> : route === '/profile' ? <ProfilePage profile={profile} /> : route === '/settings' ? <SettingsPage profile={profile} /> : route === '/teacher' ? <TeacherDashboard profile={profile} navigate={navigate} /> : route === '/admin' ? <AdminDashboard profile={profile} navigate={navigate} /> : <NotFound navigate={navigate} />;
  return <div className="app-shell">{mobileOpen && <div className="fixed inset-0 z-20 bg-[#061c2c]/40 lg:hidden" onClick={() => setMobileOpen(false)} />}<button className="fixed right-5 top-5 z-40 rounded-xl bg-[#061c2c] p-3 text-white shadow-lg lg:hidden" onClick={() => setMobileOpen(!mobileOpen)}>{mobileOpen ? <X /> : <Menu />}</button><button title={night ? 'Switch to day theme' : 'Switch to night theme'} onClick={toggleTheme} className="fixed right-20 top-5 z-40 rounded-xl border border-[#dce9e6] bg-white p-3 text-[#087f78] shadow-lg transition hover:bg-[#f0faf7]">{night ? <Sun className="h-5 w-5" /> : <Moon className="h-5 w-5" />}</button><aside className={cn('fixed inset-y-0 left-0 z-30 flex w-72 flex-col border-r border-[#dce9e6] bg-white px-5 py-6 transition-transform lg:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center gap-3 px-3"><div className="rounded-xl bg-[#087f78] p-2 text-white"><Code2 className="h-5 w-5" /></div><span className="font-bold tracking-tight text-[#102a3a]">Fullstack<span className="text-[#087f78]">Dev</span></span></div><div className="mt-10 flex items-center gap-3 rounded-2xl bg-[#f0f8f5] p-3"><Avatar profile={profile} /><div className="min-w-0"><p className="truncate text-sm font-bold text-[#102a3a]">{profile.full_name || 'Developer'}</p><p className="text-xs capitalize text-[#6c8589]">{profile.role}</p></div></div><nav className="mt-8 flex-1 space-y-1">{navItems.map((item) => { const Icon = item.icon; return <button key={item.path} onClick={() => { navigate(item.path); setMobileOpen(false); }} className={cn('flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-semibold transition', route === item.path || (item.path === '/contributions' && route.startsWith('/contributions')) ? 'bg-[#e7f7f1] text-[#087f78]' : 'text-[#6c8589] hover:bg-[#f2f8f6] hover:text-[#185464]')}><Icon className="h-[18px] w-[18px]" />{item.label}</button>; })}</nav><button onClick={() => void signOut()} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><LogOut className="h-[18px] w-[18px]" />Sign out</button></aside><main className="min-h-screen lg:pl-72"><div className="mx-auto max-w-[1440px] px-5 py-8 sm:px-8 lg:px-12 lg:py-10">{content}</div></main></div>;
}
function Avatar({ profile, size = 'md' }: { profile: Profile; size?: 'sm' | 'md' | 'lg' }): JSX.Element { const sizes = { sm: 'h-8 w-8 text-xs', md: 'h-10 w-10 text-sm', lg: 'h-20 w-20 text-2xl' }; return profile.avatar ? <img src={profile.avatar} alt={profile.full_name} className={cn('rounded-full object-cover', sizes[size])} /> : <div className={cn('flex items-center justify-center rounded-full bg-[#b9ead7] font-bold text-[#087f78]', sizes[size])}>{(profile.full_name || profile.username || 'D').slice(0, 1).toUpperCase()}</div>; }
function PageHeader({ eyebrow, title, description, action }: { eyebrow: ReactNode; title: string; description?: string; action?: ReactNode }): JSX.Element { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="mt-2 text-3xl font-bold tracking-tight text-[#102a3a] sm:text-4xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-[#6c8589]">{description}</p>}</div>{action}</div>; }
function Dashboard({ profile, navigate }: { profile: Profile; navigate: (path: string) => void }): JSX.Element { const { text: greetText, Icon: GreetIcon } = greetingInfo(); const [data, setData] = useState<{ contributions: Contribution[]; activities: Activity[]; feedback: Feedback[]; notifications: Notification[]; loading: boolean; error: string } >({ contributions: [], activities: [], feedback: [], notifications: [], loading: true, error: '' });  const load = async (): Promise<void> => { const [c, a, f, n] = await Promise.all([supabase.from('contributions').select('*, subjects(*)').eq('student_id', profile.id).order('contribution_date', { ascending: false }), supabase.from('daily_activity').select('*').eq('student_id', profile.id).order('activity_date', { ascending: false }).limit(60), supabase.from('feedback').select('*').in('contribution_id', (await supabase.from('contributions').select('id').eq('student_id', profile.id)).data?.map((x: { id: string }) => x.id) || []).order('created_at', { ascending: false }).limit(3), supabase.from('notifications').select('*').eq('user_id', profile.id).eq('read', false).order('created_at', { ascending: false }).limit(3)]); setData({ contributions: (c.data || []) as Contribution[], activities: (a.data || []) as Activity[], feedback: (f.data || []) as Feedback[], notifications: (n.data || []) as Notification[], loading: false, error: c.error || a.error ? friendlyError() : '' }); }; useEffect(() => { void load(); }, [profile.id]); useLiveRefresh(() => void load()); const avg = data.contributions.filter((c) => c.score !== null).length ? Math.round(data.contributions.filter((c) => c.score !== null).reduce((sum, c) => sum + Number(c.score), 0) / data.contributions.filter((c) => c.score !== null).length) : null; const streak = calculateStreak(data.activities); if (data.loading) return <LoadingPanel />; return <><PageHeader eyebrow={<span className="inline-flex items-center gap-1.5"><GreetIcon className="h-3.5 w-3.5" />{greetText}, {profile.full_name.split(' ')[0] || 'developer'}</span>} title="Your developer workspace" description={`${new Intl.DateTimeFormat('en', { weekday: 'long', month: 'long', day: 'numeric' }).format(new Date())}. Keep building something worth sharing.`} action={<button className="btn-primary" onClick={() => navigate('/contributions/new')}><Plus className="h-4 w-4" />New contribution</button>} />{data.error && <ErrorBanner text={data.error} />}<AdminNotesBoard navigate={navigate} profile={profile} /><div className="mt-6 grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4"><StatCard label="Total contributions" value={String(data.contributions.length)} icon={Code2} detail="Your published learning work" /><StatCard label="Average score" value={avg === null ? '—' : `${avg}%`} icon={Star} detail={avg === null ? 'Awaiting your first review' : 'Across reviewed work'} /><StatCard label="Learning streak" value={String(streak)} icon={Zap} detail={streak === 1 ? 'day in a row' : 'days in a row'} /><StatCard label="Unread updates" value={String(data.notifications.length)} icon={Bell} detail="Feedback and reminders" /></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_0.65fr]"><div className="card p-6"><div className="flex items-center justify-between"><div><p className="text-lg font-bold">Recent contributions</p><p className="mt-1 text-sm text-[#6c8589]">Your latest work and review status</p></div><button className="text-sm font-bold text-[#087f78]" onClick={() => navigate('/contributions')}>View all</button></div>{data.contributions.length === 0 ? <EmptyState icon={Code2} title="Your board is waiting" text="Create your first contribution to start tracking your learning journey." action="Create contribution" onClick={() => navigate('/contributions/new')} /> : <div className="mt-5 space-y-3">{data.contributions.slice(0, 4).map((item) => <ContributionRow key={item.id} contribution={item} onClick={() => navigate(`/contributions/${item.id}`)} />)}</div>}</div><div className="card p-6"><p className="text-lg font-bold">Activity pulse</p><p className="mt-1 text-sm text-[#6c8589]">Your last 30 days</p><ActivityGrid activities={data.activities} /></div></div><div className="mt-6 grid gap-6 lg:grid-cols-2"><div className="card p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#e7f7f1] p-2 text-[#087f78]"><Trophy className="h-5 w-5" /></div><div><p className="font-bold">Latest feedback</p><p className="text-sm text-[#6c8589]">What reviewers are saying about your work</p></div></div>{data.feedback.length ? <div className="mt-5 space-y-4">{data.feedback.map((item) => <div key={item.id} className="border-l-2 border-[#8de6c5] pl-4"><div className="flex items-center justify-between gap-2 text-xs text-[#6c8589]"><span className="flex min-w-0 flex-wrap items-center gap-2">{item.status === 'approved' ? 'Approved' : 'Needs improvement'} · {item.reviewer_name || 'Reviewer'}<RoleBadge role={item.reviewer_role} /></span><b className="shrink-0 text-[#087f78]">{item.score}%</b></div><p className="mt-1 text-sm leading-6 text-[#405e65]">{item.feedback}</p></div>)}</div> : <p className="mt-5 text-sm text-[#6c8589]">Feedback will appear here after your contribution is reviewed.</p>}</div><div className="card p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#fff7df] p-2 text-[#a47816]"><Bell className="h-5 w-5" /></div><div><p className="font-bold">Notifications</p><p className="text-sm text-[#6c8589]">Stay in the loop</p></div></div>{data.notifications.length ? <div className="mt-5 space-y-3">{data.notifications.map((n) => <div key={n.id} className="rounded-xl bg-[#f6faf8] p-3"><p className="text-sm font-semibold">{n.title}</p><p className="mt-1 text-xs leading-5 text-[#6c8589]">{n.message}</p></div>)}</div> : <p className="mt-5 text-sm text-[#6c8589]">You are all caught up.</p>}</div></div></>; }
function StatCard({ label, value, detail, icon: Icon, onClick, title }: { label: string; value: string; detail: string; icon: typeof Code2; onClick?: () => void; title?: string }): JSX.Element { const inner = <><div className="flex items-start justify-between"><div><p className="text-sm text-[#6c8589]">{label}</p><p className="mt-3 text-3xl font-bold tracking-tight text-[#102a3a]">{value}</p></div><div className="rounded-xl bg-[#e7f7f1] p-2.5 text-[#087f78]"><Icon className="h-5 w-5" /></div></div><p className="mt-3 text-xs text-[#8ca1a3]">{detail}</p></>; return onClick ? <button title={title || `View ${label.toLowerCase()}`} onClick={onClick} className="card p-5 text-left transition hover:-translate-y-0.5 hover:border-[#9ad7c5]">{inner}</button> : <div className="card p-5">{inner}</div>; }
function calculateStreak(activities: Activity[]): number { const days = new Set(activities.filter((a) => a.contribution_count > 0).map((a) => a.activity_date)); let count = 0; const cursor = new Date(); while (days.has(cursor.toISOString().slice(0, 10))) { count += 1; cursor.setDate(cursor.getDate() - 1); } return count; }
function ActivityGrid({ activities }: { activities: Activity[] }): JSX.Element { const counts = new Map(activities.map((a) => [a.activity_date, a.contribution_count])); return <div className="mt-5 grid grid-cols-10 gap-1.5 sm:grid-cols-15">{Array.from({ length: 30 }, (_, index) => { const date = new Date(); date.setDate(date.getDate() - (29 - index)); const key = date.toISOString().slice(0, 10); const count = counts.get(key) || 0; return <div key={key} title={`${key}: ${count} contribution${count === 1 ? '' : 's'}`} className={cn('aspect-square rounded-[4px]', count === 0 ? 'bg-[#edf3f1]' : count === 1 ? 'bg-[#b9ead7]' : count === 2 ? 'bg-[#5fc7aa]' : 'bg-[#087f78]')} />; })}</div>; }
function ContributionRow({ contribution, onClick }: { contribution: Contribution; onClick: () => void }): JSX.Element { return <button onClick={onClick} className="group flex w-full items-center justify-between rounded-xl border border-[#e5efec] p-4 text-left transition hover:border-[#9ad7c5] hover:bg-[#f6fcf9]"><div className="flex min-w-0 items-center gap-3"><div className="rounded-xl bg-[#edf7f4] p-2.5 text-[#087f78]"><Code2 className="h-4 w-4" /></div><div className="min-w-0"><p className="truncate text-sm font-bold text-[#185464]">{contribution.title}</p><p className="mt-1 text-xs text-[#8ca1a3]">{contribution.subjects?.name || 'Uncategorized'} · {formatDate(contribution.contribution_date)}</p></div></div><div className="flex items-center gap-3"><StatusPill status={contribution.status} />{contribution.score !== null && <span className="hidden text-sm font-bold text-[#087f78] sm:inline">{contribution.score}%</span>}<ChevronRight className="h-4 w-4 text-[#9db1b2] transition group-hover:translate-x-1" /></div></button>; }
function StatusPill({ status }: { status: string }): JSX.Element { return <span className={cn('rounded-full px-2.5 py-1 text-[10px] font-bold capitalize', status === 'approved' ? 'bg-[#e7f7f1] text-[#18704d]' : status === 'needs_improvement' ? 'bg-[#fff3df] text-[#9d6718]' : 'bg-[#edf2f2] text-[#6c8589]')}>{status.replace('_', ' ')}</span>; }
function EmptyState({ icon: Icon, title, text, action, onClick }: { icon: typeof Code2; title: string; text: string; action?: string; onClick?: () => void }): JSX.Element { return <div className="py-12 text-center"><Icon className="mx-auto h-10 w-10 text-[#9acfc0]" /><p className="mt-4 font-bold text-[#185464]">{title}</p><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[#7b9295]">{text}</p>{action && onClick && <button className="btn-secondary mt-5" onClick={onClick}>{action}</button>}</div>; }
function LoadingPanel(): JSX.Element { return <div className="card flex min-h-[320px] items-center justify-center"><div className="h-8 w-8 animate-spin rounded-full border-2 border-[#dce9e6] border-t-[#087f78]" /></div>; }
function ErrorBanner({ text }: { text: string }): JSX.Element { return <div className="mb-6 rounded-xl border border-[#f3c7c7] bg-[#fff4f4] px-4 py-3 text-sm text-[#a33b3b]">{text}</div>; }

function Contributions({ profile, navigate }: { profile: Profile; navigate: (path: string) => void }): JSX.Element { const [items, setItems] = useState<Contribution[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [subjectFilter, setSubjectFilter] = useState(''); const load = async (): Promise<void> => { const { data, error: queryError } = await supabase.from('contributions').select('*, subjects(*)').eq('student_id', profile.id).order('contribution_date', { ascending: false }); if (queryError) setError(friendlyError()); setItems((data || []) as Contribution[]); setLoading(false); }; useEffect(() => { void load(); }, [profile.id]); const remove = async (id: string): Promise<void> => { if (!window.confirm('Delete this contribution?')) return; const { error: deleteError } = await supabase.from('contributions').delete().eq('id', id).eq('student_id', profile.id); if (deleteError) setError(friendlyError()); else await load(); }; useEffect(() => { try { setSubjectFilter(new URLSearchParams(window.location.search).get('subject') || ''); } catch { /* ignore */ } }, []); return <><PageHeader eyebrow="Your work" title={subjectFilter ? `${subjectFilter} contributions` : 'Contributions'} description={subjectFilter ? `Your work in ${subjectFilter}.` : 'Capture the work you are doing as you learn.'} action={subjectFilter ? <button className="btn-secondary" onClick={() => { window.history.replaceState({}, '', '/contributions'); setSubjectFilter(''); }}><X className="h-4 w-4" />Clear filter</button> : <button className="btn-primary" onClick={() => navigate('/contributions/new')}><Plus className="h-4 w-4" />New contribution</button>} />{error && <ErrorBanner text={error} />}{loading ? <LoadingPanel /> : items.filter((i) => !subjectFilter || i.subjects?.name === subjectFilter).length === 0 ? <div className="card"><EmptyState icon={Code2} title="No contributions yet" text="Your first contribution can be a class summary, a code experiment, or a project milestone." action="Create contribution" onClick={() => navigate('/contributions/new')} /></div> : <div className="grid gap-4">{items.filter((i) => !subjectFilter || i.subjects?.name === subjectFilter).map((item) => <div key={item.id} className="card flex flex-col justify-between gap-5 p-5 sm:flex-row sm:items-center"><button className="flex min-w-0 items-center gap-4 text-left" onClick={() => navigate(`/contributions/${item.id}`)}><div className="rounded-2xl bg-[#e7f7f1] p-3 text-[#087f78]"><Code2 className="h-5 w-5" /></div><div className="min-w-0"><h3 className="truncate font-bold text-[#185464]">{item.title}</h3><p className="mt-1 line-clamp-1 text-sm text-[#6c8589]">{item.summary || 'No summary added.'}</p><p className="mt-2 text-xs text-[#8ca1a3]">{item.subjects?.name} · {formatDate(item.contribution_date)}</p></div></button><div className="flex items-center gap-2"><StatusPill status={item.status} />{item.status === 'pending' && <><button title="Edit" className="rounded-lg p-2 text-[#6c8589] hover:bg-[#edf7f4] hover:text-[#087f78]" onClick={() => navigate(`/contributions/${item.id}/edit`)}><Pencil className="h-4 w-4" /></button><button title="Delete" className="rounded-lg p-2 text-[#6c8589] hover:bg-[#fff4f4] hover:text-[#a33b3b]" onClick={() => void remove(item.id)}><Trash2 className="h-4 w-4" /></button></>}</div></div>)}</div>}</>; }

interface FormValues { title: string; subject_id: string; summary: string; description: string; code: string; github_url: string; contribution_date: string; }
function ContributionForm({ profile, navigate, contributionId }: { profile: Profile; navigate: (path: string) => void; contributionId?: string }): JSX.Element { const [subjects, setSubjects] = useState<Subject[]>([]); const [values, setValues] = useState<FormValues>({ title: '', subject_id: '', summary: '', description: '', code: '', github_url: '', contribution_date: today() }); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); useEffect(() => { (async () => { const s = await supabase.from('subjects').select('*').order('name'); setSubjects((s.data || []) as Subject[]); if (contributionId) { const c = await supabase.from('contributions').select('*').eq('id', contributionId).eq('student_id', profile.id).maybeSingle(); if (c.data) setValues({ title: c.data.title, subject_id: c.data.subject_id, summary: c.data.summary, description: c.data.description, code: c.data.code, github_url: c.data.github_url || '', contribution_date: c.data.contribution_date }); else setError('This contribution could not be found.'); } })(); }, [contributionId, profile.id]); const submit = async (event: FormEvent): Promise<void> => { event.preventDefault(); setBusy(true); setError(''); if (!values.title || !values.subject_id || !values.summary) { setError('Add a title, subject, and short summary.'); setBusy(false); return; } const payload = { ...values, github_url: values.github_url || null }; const result = contributionId ? await supabase.from('contributions').update(payload).eq('id', contributionId).eq('student_id', profile.id).select().maybeSingle() : await supabase.from('contributions').insert(payload).select().maybeSingle(); if (result.error || !result.data) { setError(friendlyError()); setBusy(false); return; } const contribution = result.data as Contribution; if (file) { const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '-'); const path = `${profile.id}/${contribution.id}/${Date.now()}-${safeName}`; const upload = await supabase.storage.from('contribution-files').upload(path, file, { contentType: file.type || 'application/octet-stream', upsert: false }); if (upload.error) { setError('The contribution saved, but the file upload failed.'); setBusy(false); return; } await supabase.from('contribution_files').insert({ contribution_id: contribution.id, file_url: path, file_name: file.name, file_type: file.type || 'application/octet-stream' }); }  const { data: existing } = await supabase.from('daily_activity').select('*').eq('student_id', profile.id).eq('activity_date', values.contribution_date).maybeSingle(); await supabase.from('daily_activity').upsert({ student_id: profile.id, activity_date: values.contribution_date, contribution_count: (existing?.contribution_count || 0) + (contributionId ? 0 : 1), daily_score: existing?.daily_score || 0 }, { onConflict: 'student_id,activity_date' }); if (!contributionId) { try { sessionStorage.setItem(`fsd_published_${contribution.id}`, '1'); } catch { /* ignore */ } } navigate(`/contributions/${contribution.id}`); }; return <><button className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-[#6c8589] hover:text-[#087f78]" onClick={() => navigate('/contributions')}><ArrowLeft className="h-4 w-4" />Back to contributions</button><PageHeader eyebrow={contributionId ? 'Edit contribution' : 'New contribution'} title={contributionId ? 'Refine your work' : 'Share what you built'} description="A clear record makes your learning easier to see and easier to review." />{error && <ErrorBanner text={error} />}<form onSubmit={submit} className="grid gap-6 lg:grid-cols-[1.2fr_0.8fr]"><div className="card space-y-5 p-6"><div><label className="mb-2 block text-sm font-semibold">Title <span className="text-[#087f78]">*</span></label><input className="field" placeholder="e.g. Built a responsive navigation system" value={values.title} onChange={(e) => setValues({ ...values, title: e.target.value })} /></div><div className="grid gap-5 sm:grid-cols-2"><div><label className="mb-2 block text-sm font-semibold">Subject <span className="text-[#087f78]">*</span></label><select className="field" value={values.subject_id} onChange={(e) => setValues({ ...values, subject_id: e.target.value })}><option value="">Choose a subject</option>{subjects.map((subject) => <option key={subject.id} value={subject.id}>{subject.name}</option>)}</select></div><div><label className="mb-2 block text-sm font-semibold">Contribution date</label><input className="field" type="date" value={values.contribution_date} onChange={(e) => setValues({ ...values, contribution_date: e.target.value })} /></div></div><div><label className="mb-2 block text-sm font-semibold">Summary <span className="text-[#087f78]">*</span></label><textarea className="field min-h-24 resize-y" placeholder="What did you learn or create?" value={values.summary} onChange={(e) => setValues({ ...values, summary: e.target.value })} /></div><div><label className="mb-2 block text-sm font-semibold">Description</label><textarea className="field min-h-32 resize-y" placeholder="Add context, decisions, and what you would improve next." value={values.description} onChange={(e) => setValues({ ...values, description: e.target.value })} /></div><div><label className="mb-2 block text-sm font-semibold">Code or notes</label><textarea className="field min-h-48 resize-y font-mono text-xs" placeholder="Paste a useful code excerpt or learning notes." value={values.code} onChange={(e) => setValues({ ...values, code: e.target.value })} /></div></div><div className="space-y-6"><div className="card p-6"><p className="font-bold">Attach a file</p><p className="mt-1 text-sm leading-6 text-[#6c8589]">Add a file from your workspace to this contribution.</p><label className="mt-5 flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#aad9ca] bg-[#f5fcf9] p-4"><Upload className="h-5 w-5 text-[#087f78]" /><div className="min-w-0"><p className="text-sm font-semibold text-[#185464]">{file ? file.name : 'Choose a file'}</p><p className="mt-1 text-xs text-[#7b9295]">Photo, video, document, or code file</p></div><input className="hidden" type="file" accept="image/*,video/*,.pdf,.txt,.md,.js,.ts,.tsx,.jsx,.css,.html,.json" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label></div><div className="card bg-[#061c2c] p-6 text-white"><p className="font-bold">Ready to submit?</p><p className="mt-2 text-sm leading-6 text-white/60">Your work will be visible to your teachers for review. You can edit it while it is pending.</p><button className="mt-5 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-[#8de6c5] px-4 py-3 text-sm font-bold text-[#062b37] transition hover:bg-[#b8f2db]" disabled={busy}>{busy ? 'Saving…' : contributionId ? 'Save changes' : 'Publish contribution'}<Check className="h-4 w-4" /></button></div></div></form></>; }

function ContributionDetail({ profile, navigate, contributionId }: { profile: Profile; navigate: (path: string) => void; contributionId: string }): JSX.Element { const [item, setItem] = useState<Contribution | null>(null); const [files, setFiles] = useState<ContributionFile[]>([]); const [feedback, setFeedback] = useState<Feedback[]>([]); const [loading, setLoading] = useState(true); const [justPublished, setJustPublished] = useState(false); const [error, setError] = useState(''); const loadFeedback = async (): Promise<void> => { const r = await supabase.from('feedback').select('*, profiles(*)').eq('contribution_id', contributionId).order('created_at', { ascending: false }); setFeedback((r.data || []) as Feedback[]); }; useEffect(() => { (async () => { const c = await supabase.from('contributions').select('*, subjects(*), profiles(*)').eq('id', contributionId).maybeSingle(); const f = await supabase.from('contribution_files').select('*').eq('contribution_id', contributionId); await loadFeedback(); setItem(c.data as Contribution | null); setFiles((f.data || []) as ContributionFile[]); try { if (sessionStorage.getItem(`fsd_published_${contributionId}`)) { setJustPublished(true); sessionStorage.removeItem(`fsd_published_${contributionId}`); } } catch { /* ignore */ } setLoading(false); })(); }, [contributionId]); const deleteFeedback = async (feedbackId: string): Promise<void> => { if (!window.confirm('Delete this review comment? This cannot be undone.')) return; setError(''); const { error: deleteError } = await supabase.from('feedback').delete().eq('id', feedbackId); if (deleteError) setError(deleteError.message || 'We could not delete that comment.'); else { await syncContributionReviewState(contributionId); await loadFeedback(); } }; if (loading) return <LoadingPanel />; if (!item) return <NotFound navigate={() => navigate('/contributions')} />; return <><button className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-[#6c8589] hover:text-[#087f78]" onClick={() => navigate('/contributions')}><ArrowLeft className="h-4 w-4" />Back to contributions</button>{justPublished && <div className="mb-6 rounded-xl border border-[#b8e6d0] bg-[#effbf5] px-4 py-3 text-sm text-[#176345]"><b>Contribution published successfully.</b> It is now pending approval and will appear in the admin dashboard for review.</div>}{error && <div className="mb-6 rounded-xl border border-[#f3c7c7] bg-[#fff4f4] px-4 py-3 text-sm text-[#a33b3b]">{error}</div>}<div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-start"><div><div className="flex flex-wrap items-center gap-3"><StatusPill status={item.status} /><span className="text-sm text-[#8ca1a3]">{item.subjects?.name} · {formatDate(item.contribution_date)}</span></div><h1 className="mt-3 text-4xl font-bold tracking-tight text-[#102a3a]">{item.title}</h1><p className="mt-3 max-w-2xl text-base leading-7 text-[#61777c]">{item.summary}</p></div>{item.student_id === profile.id && item.status === 'pending' && <button className="btn-secondary" onClick={() => navigate(`/contributions/${item.id}/edit`)}><Pencil className="h-4 w-4" />Edit</button>}</div><div className="grid gap-6 lg:grid-cols-[1.3fr_0.7fr]"><div className="space-y-6"><section className="card p-6"><h2 className="text-lg font-bold">About this contribution</h2><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-[#536e74]">{item.description || 'No additional description added.'}</p>{item.code && <CodeBlock code={item.code} />}</section>{feedback.length > 0 && <section className="card p-6"><h2 className="text-lg font-bold">Reviewer feedback</h2><div className="mt-5 space-y-5">{feedback.map((review) => <div key={review.id} className="rounded-xl bg-[#f5faf8] p-4"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><Avatar profile={review.profiles || { id: '', full_name: review.reviewer_name || 'Reviewer', username: '', avatar: null, bio: '', github_url: null, linkedin_url: null, role: 'teacher' }} size="sm" /><div className="min-w-0"><p className="flex flex-wrap items-center gap-2 text-sm font-bold"><span className="truncate">{review.reviewer_name || review.profiles?.full_name || 'Reviewer'}</span><RoleBadge role={review.reviewer_role || review.profiles?.role} /></p><p className="text-xs text-[#8ca1a3]">{formatDate(review.created_at.slice(0, 10))}</p></div></div><div className="flex items-center gap-2"><span className="font-bold text-[#087f78]">{review.score}%</span>{(profile.role === 'admin' || review.teacher_id === profile.id) && <button title={profile.role === 'admin' ? 'Delete this comment (admin)' : 'Delete this review'} onClick={() => void deleteFeedback(review.id)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div></div><p className="mt-4 text-sm leading-6 text-[#536e74]">{review.feedback}</p></div>)}</div></section>}</div><div className="space-y-6"><section className="card p-6"><p className="text-sm font-bold text-[#6c8589]">Review score</p><p className="mt-2 text-5xl font-bold text-[#087f78]">{item.score === null ? '—' : `${item.score}%`}</p><p className="mt-2 text-sm text-[#8ca1a3]">{item.score === null ? 'Awaiting teacher review' : 'Latest recorded score'}</p></section><section className="card p-6"><h2 className="font-bold">References</h2>{item.github_url && <a href={item.github_url} target="_blank" rel="noreferrer" className="mt-4 flex items-center gap-3 rounded-xl bg-[#f5faf8] p-3 text-sm font-semibold text-[#087f78] hover:bg-[#e7f7f1]"><Github className="h-4 w-4" />Open GitHub repository</a>}{files.length ? <div className="mt-3 space-y-2">{files.map((file) => <FileLink key={file.id} file={file} />)}</div> : !item.github_url && <p className="mt-4 text-sm text-[#8ca1a3]">No files or links attached.</p>}</section></div></div></>; }
// After a review is deleted, the contribution must reflect what reviewers
// actually say now: adopt the newest remaining review, or fall back to
// pending/no score when no reviews are left.
async function syncContributionReviewState(contributionId: string): Promise<void> {
  const { data } = await supabase.from('feedback').select('score, status').eq('contribution_id', contributionId).order('created_at', { ascending: false }).limit(1);
  const latest = (data || [])[0] as { score: number; status: string } | undefined;
  if (latest) await supabase.from('contributions').update({ score: Number(latest.score), status: latest.status }).eq('id', contributionId);
  else await supabase.from('contributions').update({ score: null, status: 'pending' }).eq('id', contributionId);
}

function ReviewReferences({ contributionId, githubUrl }: { contributionId: string; githubUrl?: string | null }): JSX.Element | null { const [files, setFiles] = useState<ContributionFile[]>([]); useEffect(() => { (async () => { const f = await supabase.from('contribution_files').select('*').eq('contribution_id', contributionId); setFiles((f.data || []) as ContributionFile[]); })(); }, [contributionId]); if (!files.length && !githubUrl) return null; return <div className="mt-4 border-t border-[#e5efec] pt-4"><p className="text-sm font-bold">References</p>{githubUrl && <a href={githubUrl} target="_blank" rel="noreferrer" className="mt-3 flex items-center gap-2 rounded-lg bg-white p-2.5 text-sm font-semibold text-[#087f78] hover:bg-[#e7f7f1]"><Github className="h-4 w-4" />Open GitHub repository</a>}{files.length > 0 && <div className="mt-2 space-y-2">{files.map((file) => <FileLink key={file.id} file={file} />)}</div>}</div>; }

// Full-screen in-app file viewer: opens the file in an overlay instead of
// leaving the app, so Back never kicks the user out. Works on desktop and
// mobile identically, with a big X button to close.
// Code block with a one-click copy-to-clipboard button in the corner.
function CodeBlock({ code, compact }: { code: string; compact?: boolean }): JSX.Element {
  const [copied, setCopied] = useState(false);
  const copy = async (): Promise<void> => {
    try {
      await navigator.clipboard.writeText(code);
    } catch {
      // Clipboard API can be denied (e.g. insecure context) — fall back.
      const ta = document.createElement('textarea');
      ta.value = code;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      ta.remove();
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };
  return (
    <div className="group relative mt-6">
      <pre className={`overflow-x-auto rounded-xl bg-[#061c2c] text-xs leading-6 text-[#c3e8dc] ${compact ? 'max-h-48 p-4' : 'p-5'}`}><code>{code}</code></pre>
      <button
        onClick={() => void copy()}
        title={copied ? 'Copied!' : 'Copy code'}
        className={`absolute right-2 top-2 inline-flex items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-xs font-bold transition ${copied ? 'bg-[#087f78] text-white' : 'bg-white/10 text-[#c3e8dc] hover:bg-white/20'}`}
      >
        {copied ? <Check className="h-3.5 w-3.5" /> : <ClipboardCopy className="h-3.5 w-3.5" />}
        {copied ? 'Copied' : 'Copy'}
      </button>
    </div>
  );
}

function FileViewer({ url, name, onClose }: { url: string; name: string; onClose: () => void }): JSX.Element {
  const isImage = /\.(png|jpe?g|gif|webp|svg)$/i.test(name);
  const isPdf = /\.pdf$/i.test(name);
  const [failed, setFailed] = useState(false);
  return (
    <div className="fixed inset-0 z-[70] flex flex-col bg-[#061c2c]/95 backdrop-blur-sm" onClick={onClose}>
      <div className="flex items-center justify-between gap-3 bg-[#061c2c] px-4 py-3 text-white sm:px-6">
        <p className="min-w-0 truncate text-sm font-bold">{name}</p>
        <div className="flex shrink-0 items-center gap-2">
          <a
            href={url}
            target="_blank"
            rel="noreferrer"
            title="Open in a new tab"
            className="flex h-10 items-center gap-1.5 rounded-full bg-white/10 px-3 text-xs font-bold text-white transition hover:bg-white/20"
          >
            <FileText className="h-4 w-4" />Open tab
          </a>
          <button
            onClick={onClose}
            title="Close and return"
            aria-label="Close viewer"
            className="flex h-10 w-10 items-center justify-center rounded-full bg-white/10 text-white transition hover:bg-white/20"
          >
            <X className="h-5 w-5" />
          </button>
        </div>
      </div>
      <div className="flex flex-1 items-center justify-center overflow-auto p-3 sm:p-6" onClick={(e) => e.stopPropagation()}>
        {failed ? (
          <div className="max-w-md rounded-2xl bg-white p-8 text-center shadow-2xl">
            <FileText className="mx-auto h-10 w-10 text-[#a33b3b]" />
            <p className="mt-4 break-all text-sm font-semibold">{name}</p>
            <p className="mt-2 text-sm text-[#a33b3b]">This file could not be loaded. It may have been uploaded before durable storage was enabled — remove and re-attach it once and it will work everywhere from then on.</p>
            <div className="mt-5 flex items-center justify-center gap-3">
              <a href={url} target="_blank" rel="noreferrer" className="btn-secondary text-xs">Try new tab</a>
              <button onClick={onClose} className="btn-primary text-xs">Back to app</button>
            </div>
          </div>
        ) : isImage ? (
          <img src={url} alt={name} onError={() => setFailed(true)} className="max-h-full max-w-full rounded-xl bg-white object-contain shadow-2xl" />
        ) : isPdf ? (
          <iframe src={url} title={name} onError={() => setFailed(true)} className="h-full w-full max-w-5xl rounded-xl bg-white shadow-2xl" />
        ) : (
          <div className="max-w-md rounded-2xl bg-white p-8 text-center shadow-2xl">
            <FileText className="mx-auto h-10 w-10 text-[#087f78]" />
            <p className="mt-4 break-all text-sm font-semibold">{name}</p>
            <p className="mt-2 text-xs text-[#6c8589]">This file type can't be shown inside the app.</p>
            <a href={url} target="_blank" rel="noreferrer" className="btn-primary mt-5 inline-flex">Open in new tab</a>
          </div>
        )}
      </div>
    </div>
  );
}

function FileLink({ file }: { file: ContributionFile }): JSX.Element {
  const [url, setUrl] = useState('');
  const [viewing, setViewing] = useState(false);
  useEffect(() => { (async () => { const result = await supabase.storage.from('contribution-files').createSignedUrl(file.file_url, 3600); setUrl(result.data?.signedUrl || ''); })(); }, [file.file_url]);
  return url ? <>
    <button onClick={() => setViewing(true)} className="flex w-full items-center gap-3 rounded-xl bg-[#f5faf8] p-3 text-left text-sm font-semibold text-[#087f78] transition hover:bg-[#e7f7f1]"><FileText className="h-4 w-4 shrink-0" />{file.file_name}</button>
    {viewing && <FileViewer url={url} name={file.file_name} onClose={() => setViewing(false)} />}
  </> : <div className="text-sm text-[#8ca1a3]">Loading file…</div>;
}

function Progress({ profile }: { profile: Profile }): JSX.Element { const [items, setItems] = useState<Contribution[]>([]); const [activities, setActivities] = useState<Activity[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { (async () => { const c = await supabase.from('contributions').select('*, subjects(*)').eq('student_id', profile.id); const a = await supabase.from('daily_activity').select('*').eq('student_id', profile.id).order('activity_date'); setItems((c.data || []) as Contribution[]); setActivities((a.data || []) as Activity[]); setLoading(false); })(); }, [profile.id]); if (loading) return <LoadingPanel />; const scored = items.filter((c) => c.score !== null); const average = scored.length ? Math.round(scored.reduce((sum, c) => sum + Number(c.score), 0) / scored.length) : null; const longest = longestStreak(activities); return <><PageHeader eyebrow="Your momentum" title="Progress" description="A real-time view of the work you have logged and the habits you are building." /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><StatCard label="Total contributions" value={String(items.length)} detail="All your recorded work" icon={Code2} /><StatCard label="Current streak" value={String(calculateStreak(activities))} detail="Consecutive active days" icon={Zap} /><StatCard label="Longest streak" value={String(longest)} detail="Your best run so far" icon={Trophy} /><StatCard label="Average score" value={average === null ? '—' : `${average}%`} detail="Reviewed contributions" icon={Star} /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.4fr_0.6fr]"><section className="card p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Contribution calendar</h2><p className="mt-1 text-sm text-[#6c8589]">Your daily learning activity</p></div><div className="flex items-center gap-2 text-xs text-[#8ca1a3]"><span>Less</span><i className="h-3 w-3 rounded bg-[#edf3f1]" /><i className="h-3 w-3 rounded bg-[#b9ead7]" /><i className="h-3 w-3 rounded bg-[#5fc7aa]" /><i className="h-3 w-3 rounded bg-[#087f78]" /><span>More</span></div></div><div className="mt-8"><ActivityGrid activities={activities} /></div></section><section className="card p-6"><h2 className="text-lg font-bold">Subject progress</h2><div className="mt-5 space-y-5">{(['Frontend', 'Backend', 'Cloud Computing']).map((name) => { const count = items.filter((c) => c.subjects?.name === name).length; const percent = Math.min(100, count * 20); return <div key={name}><div className="flex justify-between text-sm"><span className="font-semibold">{name}</span><span className="text-[#087f78]">{count} {count === 1 ? 'contribution' : 'contributions'}</span></div><div className="mt-2 h-2 rounded-full bg-[#e7efed]"><div className="h-2 rounded-full bg-[#53b899] transition-all" style={{ width: `${percent}%` }} /></div></div>; })}</div></section></div></>; }
function longestStreak(activities: Activity[]): number { const days = new Set(activities.filter((a) => a.contribution_count > 0).map((a) => a.activity_date)); let best = 0; days.forEach((day) => { const d = new Date(`${day}T00:00:00`); const prior = new Date(d); prior.setDate(d.getDate() - 1); if (!days.has(prior.toISOString().slice(0, 10))) { let n = 1; const next = new Date(d); next.setDate(d.getDate() + 1); while (days.has(next.toISOString().slice(0, 10))) { n++; next.setDate(next.getDate() + 1); } best = Math.max(best, n); } }); return best; }
// Per-subject syllabus board: everyone can view/open the syllabus file;
// teachers and admins upload or replace it. One syllabus per subject.
function SyllabusSection({ profile }: { profile: Profile }): JSX.Element {
  const [rows, setRows] = useState<Syllabus[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [target, setTarget] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const isStaff = profile.role === 'teacher' || profile.role === 'admin';
  const load = async (): Promise<void> => {
    const [s, subs] = await Promise.all([
      supabase.from('syllabus').select('*, subjects(id, name), profiles(full_name, role)').order('updated_at', { ascending: false }),
      supabase.from('subjects').select('*').order('name'),
    ]);
    setRows((s.data || []) as Syllabus[]);
    setSubjects((subs.data || []) as Subject[]);
  };
  useEffect(() => { void load(); }, []);
  const upload = async (): Promise<void> => {
    if (!target) { setMessage('Choose the subject this syllabus belongs to.'); return; }
    if (!file) { setMessage('Choose a PDF or image file.'); return; }
    if (!['application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type)) { setMessage('The syllabus must be a PDF or an image.'); return; }
    if (file.size > 10 * 1024 * 1024) { setMessage('Keep syllabus files under 10 MB.'); return; }
    setBusy(true); setMessage('');
    const existing = rows.find((r) => r.subject_id === target);
    const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '-');
    const path = `syllabus/${crypto.randomUUID()}-${safeName}`;
    const up = await supabase.storage.from('study-notes').upload(path, file, { contentType: file.type, upsert: false });
    if (up.error) { setMessage('The syllabus could not be uploaded. Please try again.'); setBusy(false); return; }
    const payload = { subject_id: target, title: 'Syllabus', file_path: path, file_name: file.name, file_type: file.type, uploaded_by: profile.id };
    const result = existing
      ? await supabase.from('syllabus').upsert({ ...payload, id: existing.id }, { onConflict: 'id' }).select().maybeSingle()
      : await supabase.from('syllabus').insert(payload).select().maybeSingle();
    if (result.error) { await supabase.storage.from('study-notes').remove([path]); setMessage(friendlyError()); setBusy(false); return; }
    if (existing?.file_path) await supabase.storage.from('study-notes').remove([existing.file_path]);
    setFile(null); setTarget(''); setMessage('Syllabus published.'); await load(); setBusy(false);
  };
  const remove = async (row: Syllabus): Promise<void> => {
    if (!window.confirm(`Remove the ${row.subjects?.name || ''} syllabus? Students will no longer see it.`)) return;
    const { error } = await supabase.from('syllabus').delete().eq('id', row.id);
    if (error) { setMessage(friendlyError()); return; }
    if (row.file_path) await supabase.storage.from('study-notes').remove([row.file_path]);
    await load();
  };
  const openFile = async (row: Syllabus): Promise<void> => {
    const result = await supabase.storage.from('study-notes').createSignedUrl(row.file_path, 3600);
    if (result.data?.signedUrl) setViewingSyllabus({ url: result.data.signedUrl, name: row.file_name });
  };
  const [viewingSyllabus, setViewingSyllabus] = useState<{ url: string; name: string } | null>(null);
  return <section className="mt-8"><div className="mb-5"><p className="eyebrow">Course outline</p><h2 className="mt-2 text-2xl font-bold text-[#102a3a]">Syllabus</h2><p className="mt-2 text-sm leading-6 text-[#6c8589]">The official syllabus for each subject — same document for every student.{isStaff ? ' Teachers and admins keep it up to date here.' : ''}</p></div>{message && <p className="mb-4 text-sm text-[#176345]">{message}</p>}{isStaff && <div className="card mb-4 grid gap-3 p-4 sm:grid-cols-[1fr_1.4fr_auto_auto]"><select className="field" value={target} onChange={(e) => setTarget(e.target.value)}><option value="">Subject…</option>{subjects.map((s) => <option key={s.id} value={s.id}>{s.name}{rows.some((r) => r.subject_id === s.id) ? ' (replace)' : ''}</option>)}</select><label className="btn-secondary cursor-pointer justify-center"><Upload className="h-4 w-4" />{file ? file.name : 'Choose PDF or image'}</label><input type="file" accept="application/pdf,image/*" className="hidden" onChange={(e) => setFile(e.target.files?.[0] ?? null)} /><button className="btn-primary justify-center" disabled={busy} onClick={() => void upload()}>{busy ? 'Publishing…' : 'Publish syllabus'}</button></div>}<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{subjects.map((s) => { const row = rows.find((r) => r.subject_id === s.id); return <div key={s.id} className="card flex flex-col p-5"><div className="flex items-center justify-between"><span className="rounded-full bg-[#e7f7f1] px-2.5 py-1 text-[10px] font-bold text-[#087f78]">{s.name}</span>{row && isStaff && <button title="Delete this syllabus" onClick={() => void remove(row)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div>{row ? <><p className="mt-3 truncate text-sm font-bold text-[#185464]">{row.file_name}</p><p className="mt-1 text-xs text-[#8ca1a3]">Updated {formatDate(row.updated_at?.slice(0, 10) || row.created_at.slice(0, 10))}{row.profiles ? ` · by ${row.profiles.full_name || 'staff'}` : ''}</p><button className="btn-secondary mt-4 justify-center" onClick={() => void openFile(row)}><FileText className="h-4 w-4" />View syllabus</button></> : <p className="mt-3 text-sm text-[#8ca1a3]">No syllabus published yet.{isStaff ? ' Upload it above.' : ''}</p>}</div>; })}</div>{viewingSyllabus && <FileViewer url={viewingSyllabus.url} name={viewingSyllabus.name} onClose={() => setViewingSyllabus(null)} />}</section>;
}

function LearningPath({ profile, navigate }: { profile: Profile; navigate: (path: string) => void }): JSX.Element { const [items, setItems] = useState<Contribution[]>([]); useEffect(() => { (async () => { const { data } = await supabase.from('contributions').select('*, subjects(*)').eq('student_id', profile.id); setItems((data || []) as Contribution[]); })(); }, [profile.id]); return <><PageHeader eyebrow="Keep exploring" title="Learning path" description="Your progress across the core areas of fullstack development." /><AdminNotesBoard navigate={navigate} profile={profile} /><SyllabusSection profile={profile} /><div className="mt-6 grid gap-5 md:grid-cols-3">{[{ name: 'Frontend', icon: Code2, text: 'Interfaces, accessibility, and experiences.' }, { name: 'Backend', icon: ActivityIcon, text: 'Data, APIs, and reliable application logic.' }, { name: 'Cloud Computing', icon: Cloud, text: 'Deployment, infrastructure, and scale.' }].map((path) => { const subjectItems = items.filter((item) => item.subjects?.name === path.name); const count = subjectItems.length; const Icon = path.icon; return <div key={path.name} className="card p-6"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-[#e7f7f1] text-[#087f78]"><Icon className="h-6 w-6" /></div><h2 className="mt-6 text-xl font-bold">{path.name}</h2><p className="mt-2 text-sm leading-6 text-[#6c8589]">{path.text}</p><div className="mt-6 flex items-end justify-between"><div><p className="text-3xl font-bold text-[#087f78]">{count}</p><p className="text-xs text-[#8ca1a3]">{count === 1 ? 'contribution' : 'contributions'}</p></div>{count > 0 && <button title="View these contributions" onClick={() => navigate(`/contributions?subject=${encodeURIComponent(path.name)}`)} className="inline-flex items-center gap-1.5 rounded-full bg-[#f0f8f5] px-3 py-1.5 text-xs font-bold text-[#087f78] transition hover:bg-[#e7f7f1]"><Eye className="h-4 w-4" />View</button>}</div>{count > 0 && <div className="mt-4 space-y-2">{subjectItems.slice(0, 3).map((item) => <button key={item.id} onClick={() => navigate(`/contributions/${item.id}`)} className="flex w-full items-center justify-between gap-2 rounded-lg bg-[#f6faf8] px-3 py-2 text-left transition hover:bg-[#e7f7f1]"><span className="min-w-0 truncate text-xs font-semibold text-[#185464]">{item.title}</span><StatusPill status={item.status} /></button>)}</div>}</div>; })}</div><NotesSection profile={profile} /></>; }

function NotesSection({ profile }: { profile: Profile }): JSX.Element {
  const categories = ['Frontend', 'Backend', 'Cloud Computing'] as const;
  const [notes, setNotes] = useState<StudyNote[]>([]);
  const [category, setCategory] = useState<(typeof categories)[number]>('Frontend');
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const load = async (): Promise<void> => { const result = await supabase.from('study_notes').select('*, profiles(full_name, role)').order('created_at', { ascending: false }); setNotes((result.data || []) as StudyNote[]); };
  useEffect(() => { void load(); }, [profile.id]);
  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault(); setMessage('');
    if (!title.trim() || !file) { setMessage('Add a note name and choose a PDF or image.'); return; }
    if (!['application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(file.type)) { setMessage('Notes must be a PDF or an image.'); return; }
    if (file.size > 10 * 1024 * 1024) { setMessage('Keep note files under 10 MB.'); return; }
    setBusy(true);
    const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '-');
    const path = `${profile.id}/${crypto.randomUUID()}-${safeName}`;
    const upload = await supabase.storage.from('study-notes').upload(path, file, { contentType: file.type, upsert: false });
    if (upload.error) { setMessage('The note could not be uploaded. Please try again.'); setBusy(false); return; }
    const result = await supabase.from('study_notes').insert({ category, title: title.trim(), description: description.trim(), file_path: path, file_name: file.name, file_type: file.type }).select().maybeSingle();
    if (result.error || !result.data) { await supabase.storage.from('study-notes').remove([path]); setMessage('The note could not be saved. Please try again.'); setBusy(false); return; }
    setTitle(''); setDescription(''); setFile(null); setMessage('Note uploaded successfully.'); await load(); setBusy(false);
  };
  return <section className="mt-8"><div className="mb-5"><p className="eyebrow">Your reference library</p><h2 className="mt-2 text-2xl font-bold text-[#102a3a]">Upload learning notes</h2><p className="mt-2 text-sm leading-6 text-[#6c8589]">Notes you upload are shared with everyone — students, teachers, and admins — in one learning library.</p></div><div className="grid gap-6 lg:grid-cols-[0.8fr_1.2fr]"><form onSubmit={submit} className="card space-y-4 p-6"><div><label className="mb-2 block text-sm font-semibold">Learning area</label><select className="field" value={category} onChange={(event) => setCategory(event.target.value as (typeof categories)[number])}>{categories.map((item) => <option key={item}>{item}</option>)}</select></div><div><label className="mb-2 block text-sm font-semibold">Note name</label><input className="field" placeholder="e.g. CSS grid quick reference" value={title} onChange={(event) => setTitle(event.target.value)} /></div><div><label className="mb-2 block text-sm font-semibold">Description</label><textarea className="field min-h-28 resize-y" placeholder="What does this note cover?" value={description} onChange={(event) => setDescription(event.target.value)} /></div><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#aad9ca] bg-[#f5fcf9] p-4"><Upload className="h-5 w-5 text-[#087f78]" /><div className="min-w-0"><p className="truncate text-sm font-semibold text-[#185464]">{file ? file.name : 'Choose a PDF or image'}</p><p className="mt-1 text-xs text-[#7b9295]">PDF, JPG, PNG, WEBP, or GIF · 10 MB maximum</p></div><input className="hidden" type="file" accept="application/pdf,image/jpeg,image/png,image/webp,image/gif" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label>{message && <p className="text-sm text-[#176345]">{message}</p>}<button className="btn-primary w-full" disabled={busy}>{busy ? 'Uploading…' : 'Upload note'}<Upload className="h-4 w-4" /></button></form><div className="space-y-3">{notes.length === 0 ? <div className="card p-8 text-center"><FileText className="mx-auto h-9 w-9 text-[#9acfc0]" /><p className="mt-3 font-bold text-[#185464]">No notes in the library yet</p><p className="mt-1 text-sm text-[#7b9295]">Upload the first reference — everyone will see it here.</p></div> : notes.map((note) => <NoteCard key={note.id} note={note} profile={profile} onChanged={load} />)}</div></div></section>;
}

function NoteCard({ note, profile, onChanged }: { note: StudyNote; profile: Profile; onChanged: () => Promise<void> | void }): JSX.Element {
  const [url, setUrl] = useState('');
  const [viewing, setViewing] = useState(false);
  const [managing, setManaging] = useState(false);
  const canManage = note.user_id === profile.id || profile.role === 'admin';
  useEffect(() => { (async () => { const result = await supabase.storage.from('study-notes').createSignedUrl(note.file_path, 3600); setUrl(result.data?.signedUrl || ''); })(); }, [note.file_path]);
  return <div className="card flex flex-col gap-4 p-5 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-[#e7f7f1] px-2.5 py-1 text-[10px] font-bold text-[#087f78]">{note.category}</span><span className="text-xs text-[#8ca1a3]">{new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(note.created_at))}</span>{note.profiles && <span className="flex items-center gap-1 text-xs font-semibold text-[#536e74]">{note.profiles.role === 'teacher' ? 'Teacher' : note.profiles.role === 'admin' ? 'Admin' : 'Student'}: {note.profiles.full_name || 'Member'}</span>}</div><h3 className="mt-3 font-bold text-[#185464]">{note.title}</h3>{note.description && <p className="mt-1 text-sm leading-6 text-[#6c8589]">{note.description}</p>}<p className="mt-3 truncate text-xs text-[#8ca1a3]">{note.file_name}</p></div><div className="flex shrink-0 items-center gap-2">{url ? <button onClick={() => setViewing(true)} className="btn-secondary"><FileText className="h-4 w-4" />Open note</button> : <span className="text-xs text-[#8ca1a3]">Preparing file…</span>}{canManage && <button title="View and edit this note" onClick={() => setManaging(true)} className="rounded-lg p-2.5 text-[#6c8589] transition hover:bg-[#eef7f4] hover:text-[#087f78]"><Eye className="h-4 w-4" /></button>}</div>{viewing && url && <FileViewer url={url} name={note.file_name || note.title} onClose={() => setViewing(false)} />}{managing && <NoteManageModal note={note} onClose={() => setManaging(false)} onChanged={onChanged} />}</div>;
}

// Eye-button modal: edit the note's text, replace or remove the file, or
// delete the note entirely. Owner or admin only (the button is hidden for
// everyone else, and the server enforces the same rule).
function NoteManageModal({ note, onClose, onChanged }: { note: StudyNote; onClose: () => void; onChanged: () => Promise<void> | void }): JSX.Element {
  const categories = ['Frontend', 'Backend', 'Cloud Computing'];
  const [title, setTitle] = useState(note.title);
  const [description, setDescription] = useState(note.description || '');
  const [category, setCategory] = useState<string>(note.category);
  const [newFile, setNewFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const saveText = async (): Promise<void> => {
    if (!title.trim()) { setMessage('The note needs a name.'); return; }
    setBusy(true); setMessage('');
    const { error } = await supabase.from('study_notes').update({ title: title.trim(), description: description.trim(), category }).eq('id', note.id).eq('user_id', note.user_id);
    setBusy(false);
    if (error) { setMessage(friendlyError()); return; }
    await onChanged();
    onClose();
  };
  const replaceFile = async (): Promise<void> => {
    if (!newFile) { setMessage('Choose a new file first.'); return; }
    if (!['application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(newFile.type)) { setMessage('Notes must be a PDF or an image.'); return; }
    if (newFile.size > 10 * 1024 * 1024) { setMessage('Keep note files under 10 MB.'); return; }
    setBusy(true); setMessage('');
    const safeName = newFile.name.replace(/[^a-zA-Z0-9._-]/g, '-');
    const path = `${note.user_id}/${crypto.randomUUID()}-${safeName}`;
    const upload = await supabase.storage.from('study-notes').upload(path, newFile, { contentType: newFile.type, upsert: false });
    if (upload.error) { setMessage('The new file could not be uploaded.'); setBusy(false); return; }
    const { error } = await supabase.from('study_notes').update({ file_path: path, file_name: newFile.name, file_type: newFile.type }).eq('id', note.id).eq('user_id', note.user_id);
    if (error) { await supabase.storage.from('study-notes').remove([path]); setMessage(friendlyError()); setBusy(false); return; }
    await supabase.storage.from('study-notes').remove([note.file_path]);
    await onChanged();
    onClose();
  };
  const removeFile = async (): Promise<void> => {
    if (!window.confirm('Remove the attached file from this note? The note stays, without a file.')) return;
    setBusy(true); setMessage('');
    const { error } = await supabase.from('study_notes').update({ file_path: '', file_name: '', file_type: '' }).eq('id', note.id).eq('user_id', note.user_id);
    setBusy(false);
    if (error) { setMessage(friendlyError()); return; }
    await supabase.storage.from('study-notes').remove([note.file_path]);
    await onChanged();
    onClose();
  };
  const deleteNote = async (): Promise<void> => {
    if (!window.confirm('Delete this note permanently? This cannot be undone.')) return;
    setBusy(true); setMessage('');
    const { error } = await supabase.from('study_notes').delete().eq('id', note.id).eq('user_id', note.user_id);
    if (error) { setBusy(false); setMessage(friendlyError()); return; }
    if (note.file_path) await supabase.storage.from('study-notes').remove([note.file_path]);
    await onChanged();
    onClose();
  };
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#061c2c]/60 p-4" onClick={onClose}><div className="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-6" onClick={(e) => e.stopPropagation()}><div className="flex items-start justify-between"><div><p className="eyebrow">Manage note</p><h2 className="mt-2 text-xl font-bold">{note.title}</h2></div><button onClick={onClose} className="rounded-lg p-2 hover:bg-[#f2f8f6]"><X className="h-5 w-5" /></button></div>{message && <p className="mt-3 text-sm text-[#a33b3b]">{message}</p>}<div className="mt-5 space-y-4"><div><label className="mb-2 block text-sm font-semibold">Learning area</label><select className="field" value={category} onChange={(e) => setCategory(e.target.value)}>{categories.map((c) => <option key={c}>{c}</option>)}</select></div><div><label className="mb-2 block text-sm font-semibold">Note name</label><input className="field" value={title} onChange={(e) => setTitle(e.target.value)} /></div><div><label className="mb-2 block text-sm font-semibold">Description</label><textarea className="field min-h-20" value={description} onChange={(e) => setDescription(e.target.value)} /></div><div><label className="mb-2 block text-sm font-semibold">Attached file</label><p className="mb-2 truncate text-xs text-[#8ca1a3]">Current: {note.file_name || 'none'}</p><div className="flex flex-wrap items-center gap-2"><label className="btn-secondary cursor-pointer text-xs"><Upload className="h-3.5 w-3.5" />{newFile ? newFile.name : 'Replace file'}</label><input type="file" accept="application/pdf,image/*" className="hidden" onChange={(e) => setNewFile(e.target.files?.[0] ?? null)} />{note.file_name && <button type="button" className="text-xs font-semibold text-[#a33b3b]" onClick={() => void removeFile()}>Remove file</button>}</div></div></div><div className="mt-6 flex items-center justify-between gap-3"><button className="text-sm font-semibold text-[#a33b3b] transition hover:text-[#7d2b2b]" onClick={() => void deleteNote()}><span className="inline-flex items-center gap-1.5"><Trash2 className="h-4 w-4" />Delete note</span></button><div className="flex items-center gap-2"><button className="btn-secondary text-sm" onClick={onClose}>Cancel</button><button className="btn-primary text-sm" disabled={busy} onClick={() => void saveText()}>{busy ? 'Saving…' : 'Save changes'}</button></div></div><button className="mt-4 w-full rounded-lg bg-[#f5faf8] px-3 py-2 text-xs font-semibold text-[#087f78]" disabled={busy || !newFile} onClick={() => void replaceFile()}>{busy ? 'Uploading…' : 'Save new file (uploads the chosen replacement)'}</button></div></div>;
}

function Students({ navigate }: { navigate: (path: string) => void }): JSX.Element { const [people, setPeople] = useState<Profile[]>([]); const [search, setSearch] = useState(''); const [roleFilter, setRoleFilter] = useState<'student' | 'teacher' | 'all'>('student'); useEffect(() => { (async () => { const { data } = await supabase.from('profiles').select('*').in('role', ['student', 'teacher']).order('full_name'); setPeople((data || []) as Profile[]); })(); }, []); const filtered = people.filter((s) => (roleFilter === 'all' || s.role === roleFilter) && `${s.full_name} ${s.username}`.toLowerCase().includes(search.toLowerCase())); return <><PageHeader eyebrow="Community" title="Student & teacher directory" description="Browse the people on the platform and explore the work they share." /><div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center"><div className="grid max-w-md flex-1 grid-cols-3 gap-2 rounded-xl bg-[#e4f0ed] p-1"><button className={cn('rounded-lg px-3 py-2 text-sm font-semibold transition', roleFilter === 'student' ? 'bg-white text-[#087f78] shadow-sm' : 'text-[#61777c]')} onClick={() => setRoleFilter('student')}>Students</button><button className={cn('rounded-lg px-3 py-2 text-sm font-semibold transition', roleFilter === 'teacher' ? 'bg-white text-[#087f78] shadow-sm' : 'text-[#61777c]')} onClick={() => setRoleFilter('teacher')}>Teachers</button><button className={cn('rounded-lg px-3 py-2 text-sm font-semibold transition', roleFilter === 'all' ? 'bg-white text-[#087f78] shadow-sm' : 'text-[#61777c]')} onClick={() => setRoleFilter('all')}>Everyone</button></div><div className="relative max-w-md flex-1"><Search className="absolute left-3 top-3.5 h-4 w-4 text-[#8ca1a3]" /><input className="field pl-10" placeholder="Search by name or username" value={search} onChange={(e) => setSearch(e.target.value)} /></div></div>{filtered.length === 0 ? <div className="card"><EmptyState icon={Users} title="No one found" text="Try a different search or filter." /></div> : <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filtered.map((person) => <div key={person.id} className="card flex items-center gap-4 p-5 transition hover:-translate-y-0.5 hover:border-[#9ad7c5]"><button className="flex min-w-0 flex-1 items-center gap-4 text-left" onClick={() => navigate(`/students/${person.id}`)}><Avatar profile={person} /><div className="min-w-0"><div className="flex items-center gap-2"><p className="truncate font-bold text-[#185464]">{person.full_name || 'Unnamed member'}</p><span className={cn('shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide', person.role === 'teacher' ? 'bg-[#fff7df] text-[#a47816]' : 'bg-[#e7f7f1] text-[#087f78]')}>{person.role}</span></div><p className="mt-1 truncate text-sm text-[#6c8589]">@{person.username || 'member'}</p><p className="mt-3 line-clamp-2 text-xs leading-5 text-[#8ca1a3]">{person.bio || (person.role === 'teacher' ? 'Teaching on the platform.' : 'Learning in public.')}</p></div></button><button title={`View ${person.role === 'teacher' ? 'contributions' : 'work'}`} onClick={() => navigate(`/students/${person.id}`)} className="ml-auto shrink-0 rounded-lg p-2 text-[#6c8589] transition hover:bg-[#e7f7f1] hover:text-[#087f78]"><Eye className="h-5 w-5" /></button></div>)}</div>}</>; }
function StudentDetail({ navigate, studentId }: { navigate: (path: string) => void; studentId: string }): JSX.Element { const [student, setStudent] = useState<Profile | null>(null); const [items, setItems] = useState<Contribution[]>([]); const [feedback, setFeedback] = useState<Record<string, Feedback[]>>({}); const [loading, setLoading] = useState(true); useEffect(() => { (async () => { const p = await supabase.from('profiles').select('*').in('role', ['student', 'teacher']).eq('id', studentId).maybeSingle(); const c = await supabase.from('contributions').select('*, subjects(*)').eq('student_id', studentId).eq('status', 'approved').order('contribution_date', { ascending: false }); const list = (c.data || []) as Contribution[]; const ids = list.map((x) => x.id); const fb = ids.length ? await supabase.from('feedback').select('*, profiles(role)').in('contribution_id', ids).order('created_at', { ascending: false }) : { data: [] as Feedback[] | null }; const grouped: Record<string, Feedback[]> = {}; for (const f of (fb.data || []) as Feedback[]) { (grouped[f.contribution_id] ||= []).push(f); } setStudent(p.data as Profile | null); setItems(list); setFeedback(grouped); setLoading(false); })(); }, [studentId]); if (loading) return <LoadingPanel />; if (!student) return <NotFound navigate={() => navigate('/students')} />; return <><div className="card mb-6 bg-[#061c2c] p-7 text-white"><div className="flex flex-col gap-5 sm:flex-row sm:items-center"><Avatar profile={student} size="lg" /><div><p className="eyebrow text-[#8de6c5]">{student.role === 'teacher' ? 'Teacher profile' : 'Student profile'}</p><h1 className="mt-2 text-3xl font-bold">{student.full_name || 'Student'}</h1><p className="mt-1 text-sm text-white/60">@{student.username || 'student'}</p></div></div><p className="mt-6 max-w-2xl text-sm leading-7 text-white/70">{student.bio || `This ${student.role === 'teacher' ? 'teacher' : 'student'} has not added a bio yet.`}</p><div className="mt-6 flex flex-wrap gap-3">{student.github_url && <a className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-3 py-2 text-sm font-semibold hover:bg-white/20" href={student.github_url} target="_blank" rel="noreferrer"><Github className="h-4 w-4" />GitHub</a>}{student.linkedin_url && <a className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-3 py-2 text-sm font-semibold hover:bg-white/20" href={student.linkedin_url} target="_blank" rel="noreferrer"><LinkIcon className="h-4 w-4" />LinkedIn</a>}</div></div><PageHeader eyebrow="Public work" title="Approved contributions" description={`${items.length} approved ${items.length === 1 ? 'contribution' : 'contributions'} shared with the community.`} />{items.length ? <div className="grid gap-4">{items.map((item) => <div key={item.id} className="card flex flex-col gap-4 p-5"><div className="flex items-center justify-between gap-4"><button className="flex min-w-0 flex-1 items-center gap-4 text-left" onClick={() => navigate(`/contributions/${item.id}`)}><div className="rounded-2xl bg-[#e7f7f1] p-3 text-[#087f78]"><Code2 className="h-5 w-5" /></div><div className="min-w-0"><h3 className="truncate font-bold text-[#185464]">{item.title}</h3><p className="mt-1 truncate text-sm text-[#6c8589]">{item.summary || 'No summary added.'}</p><p className="mt-2 text-xs text-[#8ca1a3]">{item.subjects?.name} · {formatDate(item.contribution_date)}</p></div></button><div className="flex shrink-0 items-center gap-3"><StatusPill status={item.status} />{item.score !== null && <span className="text-sm font-bold text-[#087f78]">{item.score}%</span>}<button title="View contribution" onClick={() => navigate(`/contributions/${item.id}`)} className="rounded-lg p-2 text-[#6c8589] transition hover:bg-[#e7f7f1] hover:text-[#087f78]"><Eye className="h-5 w-5" /></button></div></div>{feedback[item.id]?.length ? <div className="space-y-2 border-t border-[#e5efec] pt-3">{feedback[item.id].slice(0, 2).map((fb) => <div key={fb.id} className="rounded-xl bg-[#f6faf8] p-3"><div className="flex justify-between text-xs text-[#6c8589]"><span className="flex min-w-0 flex-wrap items-center gap-2"><span className="font-semibold">{fb.reviewer_name || 'Reviewer'}</span><RoleBadge role={fb.reviewer_role || fb.profiles?.role} /></span><b className="shrink-0 text-[#087f78]">{fb.score}%</b></div><p className="mt-1 text-sm leading-5 text-[#536e74]">{fb.feedback}</p></div>)}</div> : null}</div>)} </div> : <div className="card"><EmptyState icon={BookOpen} title="No public work yet" text="Approved contributions will appear here." /></div>}</>; }

function Notifications({ profile }: { profile: Profile }): JSX.Element { const [items, setItems] = useState<Notification[]>([]); const [people, setPeople] = useState<Profile[]>([]); const [loading, setLoading] = useState(true); const [to, setTo] = useState(''); const [nTitle, setNTitle] = useState(''); const [nMsg, setNMsg] = useState(''); const [sending, setSending] = useState(false); const [notice, setNotice] = useState(''); const load = async (): Promise<void> => { const { data } = await supabase.from('notifications').select('*').eq('user_id', profile.id).order('created_at', { ascending: false }); setItems((data || []) as Notification[]); setLoading(false); }; const loadPeople = async (): Promise<void> => { const { data } = await supabase.from('profiles').select('id, full_name, username, avatar, bio, github_url, linkedin_url, role').neq('id', profile.id).order('full_name'); setPeople((data || []) as Profile[]); }; useEffect(() => { void load(); void loadPeople(); }, [profile.id]); useLiveRefresh(() => void load());  const markRead = async (item: Notification): Promise<void> => { await supabase.from('notifications').update({ read: true }).eq('id', item.id).eq('user_id', profile.id); await load(); }; const removeOne = async (item: Notification): Promise<void> => { const { error } = await supabase.from('notifications').delete().eq('id', item.id).eq('user_id', profile.id); if (!error) await load(); }; const removeAll = async (): Promise<void> => { if (!window.confirm('Delete all of your notifications? This cannot be undone.')) return; for (const item of items) { await supabase.from('notifications').delete().eq('id', item.id).eq('user_id', profile.id); } await load(); }; const send = async (event: FormEvent): Promise<void> => { event.preventDefault(); if (!to || !nTitle.trim() || !nMsg.trim()) { setNotice('Choose a recipient and fill in both fields.'); return; } setSending(true); setNotice(''); const { error } = await supabase.from('notifications').insert({ user_id: to, title: nTitle.trim(), message: nMsg.trim(), type: 'message' }); setSending(false); if (error) { setNotice(friendlyError()); return; } setNTitle(''); setNMsg(''); setNotice('Notification sent.'); };
  const senderIcon = (n: Notification): JSX.Element => { const r = n.sender_role || 'system'; const s = roleStyles[r] || roleStyles.student; const Icon = r === 'system' ? Bell : s.icon; return <div className={cn('rounded-xl p-2.5', r === 'admin' ? 'bg-[#ede9fe] text-[#6d5ae0]' : r === 'teacher' ? 'bg-[#fff7df] text-[#a47816]' : 'bg-[#e7f7f1] text-[#087f78]')}><Icon className="h-5 w-5" /></div>; };
  return <><PageHeader eyebrow="Stay current" title="Notifications" description="Feedback, approvals, and messages from across your workspace." />
    <section className="card mb-6 p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#e7f7f1] p-2.5 text-[#087f78]"><Megaphone className="h-5 w-5" /></div><div><h2 className="font-bold">Send a notification</h2><p className="mt-0.5 text-sm text-[#6c8589]">Message any member — admins, teachers, and students can all reach each other.</p></div></div>{notice && <p className="mt-3 text-sm text-[#176345]">{notice}</p>}<form onSubmit={send} className="mt-4 grid gap-3 sm:grid-cols-[1fr_1.2fr_1.4fr_auto]"><select className="field" value={to} onChange={(e) => setTo(e.target.value)}><option value="">Choose recipient…</option>{people.map((p) => <option key={p.id} value={p.id}>{p.full_name || p.username} · {p.role}</option>)}</select><input className="field" placeholder="Title" value={nTitle} onChange={(e) => setNTitle(e.target.value)} /><input className="field" placeholder="Message" value={nMsg} onChange={(e) => setNMsg(e.target.value)} /><button className="btn-primary inline-flex items-center justify-center gap-2" disabled={sending}>{sending ? 'Sending…' : <><Send className="h-4 w-4" />Send</>}</button></form></section>
    {loading ? <LoadingPanel /> : items.length === 0 ? <div className="card"><EmptyState icon={Bell} title="You are all caught up" text="New updates will show up here." /></div> : <><div className="mb-3 flex justify-end"><button className="text-sm font-semibold text-[#6c8589] transition hover:text-[#a33b3b]" onClick={() => void removeAll()}>Delete all</button></div><div className="space-y-3">{items.map((item) => <div key={item.id} className={cn('card flex w-full items-start gap-4 p-5', !item.read && 'border-l-4 border-l-[#087f78]')}>{senderIcon(item)}<button onClick={() => void markRead(item)} className="min-w-0 flex-1 text-left"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-bold">{item.title}</p><span className="shrink-0 text-xs text-[#8ca1a3]">{formatDate(item.created_at.slice(0, 10))}</span></div>{item.sender_name && <p className="mt-1 flex items-center gap-2 text-xs text-[#6c8589]"><span className="font-semibold">From {item.sender_name}</span><RoleBadge role={item.sender_role} /></p>}<p className="mt-2 text-sm leading-6 text-[#6c8589]">{item.message}</p>{!item.read && <p className="mt-3 text-xs font-bold text-[#087f78]">Click to mark as read</p>}</button><button title="Delete this notification" onClick={() => void removeOne(item)} className="shrink-0 rounded-lg p-2 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button></div>)}</div></>}</>; }

function ProfilePage({ profile }: { profile: Profile }): JSX.Element { const [values, setValues] = useState(profile); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const save = async (event: FormEvent): Promise<void> => { event.preventDefault(); setBusy(true); setMessage(''); const { error } = await supabase.from('profiles').update({ full_name: values.full_name, username: values.username, avatar: values.avatar, bio: values.bio, github_url: values.github_url, linkedin_url: values.linkedin_url }).eq('id', profile.id); setMessage(error ? friendlyError() : 'Profile saved successfully.'); setBusy(false); }; return <><PageHeader eyebrow="Your identity" title="Profile" description="Keep the details that represent you and your work up to date." /><form onSubmit={save} className="grid gap-6 lg:grid-cols-[0.7fr_1.3fr]"><div className="card flex flex-col items-center justify-center p-8 text-center"><Avatar profile={values} size="lg" /><p className="mt-4 font-bold">{values.full_name || 'Your name'}</p><p className="mt-1 text-sm text-[#6c8589]">{values.role}</p></div><div className="card space-y-5 p-6">{message && <div className="rounded-xl bg-[#effbf5] px-4 py-3 text-sm text-[#176345]">{message}</div>}<div className="grid gap-5 sm:grid-cols-2"><div><label className="mb-2 block text-sm font-semibold">Full name</label><input className="field" value={values.full_name} onChange={(e) => setValues({ ...values, full_name: e.target.value })} /></div><div><label className="mb-2 block text-sm font-semibold">Username</label><input className="field" value={values.username} onChange={(e) => setValues({ ...values, username: e.target.value })} /></div></div><div><label className="mb-2 block text-sm font-semibold">Avatar URL</label><input className="field" type="url" value={values.avatar || ''} onChange={(e) => setValues({ ...values, avatar: e.target.value || null })} /></div><div><label className="mb-2 block text-sm font-semibold">Bio</label><textarea className="field min-h-28" value={values.bio} onChange={(e) => setValues({ ...values, bio: e.target.value })} /></div><div className="grid gap-5 sm:grid-cols-2"><div><label className="mb-2 block text-sm font-semibold">GitHub URL</label><input className="field" type="url" value={values.github_url || ''} onChange={(e) => setValues({ ...values, github_url: e.target.value || null })} /></div><div><label className="mb-2 block text-sm font-semibold">LinkedIn URL</label><input className="field" type="url" value={values.linkedin_url || ''} onChange={(e) => setValues({ ...values, linkedin_url: e.target.value || null })} /></div></div><button className="btn-primary" disabled={busy}>{busy ? 'Saving…' : 'Save profile'}</button></div></form></>; }
function SettingsPage({ profile }: { profile: Profile }): JSX.Element { const [resetMessage, setResetMessage] = useState(''); const [resetLink, setResetLink] = useState(''); const [busy, setBusy] = useState(false); const [links, setLinks] = useState({ github_url: profile.github_url || '', linkedin_url: profile.linkedin_url || '' }); const [linksBusy, setLinksBusy] = useState(false); const [linksMessage, setLinksMessage] = useState(''); const saveLinks = async (event: FormEvent): Promise<void> => { event.preventDefault(); setLinksBusy(true); setLinksMessage(''); const { error } = await supabase.from('profiles').update({ github_url: links.github_url.trim() || null, linkedin_url: links.linkedin_url.trim() || null }).eq('id', profile.id); setLinksMessage(error ? friendlyError() : 'Links saved.'); setLinksBusy(false); }; const reset = async (): Promise<void> => { setBusy(true); setResetLink(''); setResetMessage(''); const email = (await supabase.auth.getUser()).data.user?.email || ''; const { data, error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/reset-password` }); setBusy(false); if (error) { setResetMessage('We could not prepare a reset link right now. Please try again.'); return; } setResetLink(`${window.location.origin}/reset-password?email=${encodeURIComponent(email)}&token=${data?.code ?? ''}`); setResetMessage('Your secure reset link is ready below.'); }; return <><PageHeader eyebrow="Workspace" title="Settings" description="Manage account access and preferences." /><div className="max-w-2xl space-y-5"><div className="card p-6"><div className="flex items-start gap-4"><div className="rounded-xl bg-[#e7f7f1] p-3 text-[#087f78]"><Github className="h-5 w-5" /></div><div className="min-w-0 flex-1"><h2 className="font-bold">Profile links</h2><p className="mt-2 text-sm leading-6 text-[#6c8589]">Your GitHub and LinkedIn show on your public profile for every role — student, teacher, and admin.</p><form onSubmit={saveLinks} className="mt-4 space-y-3"><div><label className="mb-2 block text-sm font-semibold">GitHub URL</label><div className="relative"><Github className="absolute left-3 top-3.5 h-4 w-4 text-[#8ca1a3]" /><input className="field pl-10" type="url" placeholder="https://github.com/yourname" value={links.github_url} onChange={(e) => setLinks({ ...links, github_url: e.target.value })} /></div></div><div><label className="mb-2 block text-sm font-semibold">LinkedIn URL</label><div className="relative"><LinkIcon className="absolute left-3 top-3.5 h-4 w-4 text-[#8ca1a3]" /><input className="field pl-10" type="url" placeholder="https://linkedin.com/in/yourname" value={links.linkedin_url} onChange={(e) => setLinks({ ...links, linkedin_url: e.target.value })} /></div></div><button className="btn-primary" disabled={linksBusy}>{linksBusy ? 'Saving…' : 'Save links'}</button></form>{linksMessage && <p className="mt-3 text-sm text-[#176345]">{linksMessage}</p>}</div></div></div><div className="card p-6"><div className="flex items-start gap-4"><div className="rounded-xl bg-[#e7f7f1] p-3 text-[#087f78]"><Settings className="h-5 w-5" /></div><div><h2 className="font-bold">Account security</h2><p className="mt-2 text-sm leading-6 text-[#6c8589]">Reset your password whenever you need to. We will prepare a secure link to your account email that opens the reset page.</p><button className="btn-secondary mt-5" disabled={busy} onClick={() => void reset()}>{busy ? 'Preparing…' : 'Send password reset'}</button>{resetMessage && <p className="mt-3 text-sm text-[#176345]">{resetMessage}</p>}{resetLink && <a className="mt-2 inline-block text-sm font-bold text-[#087f78] underline" href={resetLink}>Click here to set a new password</a>}</div></div></div><div className="card p-6"><h2 className="font-bold">Signed in as</h2><p className="mt-2 text-sm text-[#6c8589]">{profile.full_name || profile.username || 'Developer'} · {profile.role}</p></div></div></>; }

function TeacherDashboard({ profile, navigate }: { profile: Profile; navigate: (path: string) => void }): JSX.Element { const { text: greetText, Icon: GreetIcon } = greetingInfo(); const [items, setItems] = useState<Contribution[]>([]); const [students, setStudents] = useState<Profile[]>([]); const [selected, setSelected] = useState<Contribution | null>(null); const [review, setReview] = useState({ feedback: '', score: '80', status: 'approved' as 'approved' | 'needs_improvement' }); const [message, setMessage] = useState(''); const [selectedReviews, setSelectedReviews] = useState<Feedback[]>([]); const [rowReviews, setRowReviews] = useState<Record<string, { id: string; teacher_id: string }[]>>({}); const load = async (): Promise<void> => { const c = await supabase.from('contributions').select('*, subjects(*), profiles(*)').order('created_at', { ascending: false }); const s = await supabase.from('profiles').select('*').eq('role', 'student'); const fb = await supabase.from('feedback').select('id, contribution_id, teacher_id'); const reviewMap: Record<string, { id: string; teacher_id: string }[]> = {}; for (const f of (fb.data || []) as { id: string; contribution_id: string; teacher_id: string }[]) { (reviewMap[f.contribution_id] ||= []).push({ id: f.id, teacher_id: f.teacher_id }); } setRowReviews(reviewMap); setItems((c.data || []) as Contribution[]); setStudents((s.data || []) as Profile[]); }; useEffect(() => { void load(); }, []); useEffect(() => { (async () => { if (!selected) { setSelectedReviews([]); return; } const r = await supabase.from('feedback').select('*').eq('contribution_id', selected.id).order('created_at', { ascending: false }); setSelectedReviews((r.data || []) as Feedback[]); })(); }, [selected]); const removeReview = async (id: string): Promise<void> => { if (!window.confirm('Delete this review? The student will no longer see this feedback.')) return; const { error } = await supabase.from('feedback').delete().eq('id', id).eq('teacher_id', profile.id); if (error) setMessage(friendlyError()); else { setMessage('Review deleted.'); setSelectedReviews((rows) => rows.filter((r) => r.id !== id)); if (selected) await syncContributionReviewState(selected.id); } await load(); }; const removeMyReviewForRow = async (contributionId: string): Promise<void> => { const all = rowReviews[contributionId] || []; const mine = profile.role === 'admin' ? all : all.filter((r) => r.teacher_id === profile.id); if (!mine.length) return; if (!window.confirm(profile.role === 'admin' ? `Delete all ${mine.length} review(s) of this work?` : 'Delete your review of this work? The student will no longer see this feedback.')) return; let failed = false; for (const r of mine) { let del = supabase.from('feedback').delete().eq('id', r.id); if (profile.role !== 'admin') del = del.eq('teacher_id', profile.id); const { error } = await del; if (error) failed = true; } if (failed) setMessage(friendlyError()); else { setMessage(mine.length > 1 ? `${mine.length} reviews deleted.` : 'Your review was deleted.'); await syncContributionReviewState(contributionId); } await load(); }; const submitReview = async (event: FormEvent): Promise<void> => { event.preventDefault(); if (!selected || !review.feedback || Number(review.score) < 0 || Number(review.score) > 100) return; const { error } = await supabase.from('feedback').insert({ contribution_id: selected.id, teacher_id: profile.id, reviewer_name: profile.full_name || 'Teacher', reviewer_role: 'teacher', feedback: review.feedback, score: Number(review.score), status: review.status }); if (!error) { await supabase.from('contributions').update({ score: Number(review.score), status: review.status }).eq('id', selected.id); await supabase.from('notifications').insert({ user_id: selected.student_id, title: review.status === 'approved' ? 'Contribution approved' : 'Feedback on your contribution', message: review.feedback, type: review.status }); setMessage('Review saved and the student has been notified.'); setSelected(null); setReview({ feedback: '', score: '80', status: 'approved' }); await load(); } else setMessage(friendlyError()); }; const pending = items.filter((i) => i.status === 'pending'); return <><PageHeader eyebrow={<span className="inline-flex items-center gap-1.5"><GreetIcon className="h-3.5 w-3.5" />{greetText}, {profile.full_name.split(' ')[0] || 'teacher'}</span>} title="Teacher workspace" description="Review real student work, give useful feedback, and help the next contribution get stronger." /><div className="grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4"><StatCard label="Total students" value={String(students.length)} detail="Student profiles" icon={Users} /><StatCard label="Active students" value={String(new Set(items.map((i) => i.student_id)).size)} detail="With recorded contributions" icon={Zap} /><StatCard label="Today's work" value={String(items.filter((i) => i.contribution_date === today()).length)} detail="Contributions logged today" icon={ActivityIcon} /><StatCard label="Pending reviews" value={String(pending.length)} detail="Ready for your attention" icon={ListChecks} /></div>{message && <div className="mt-6 rounded-xl bg-[#effbf5] px-4 py-3 text-sm text-[#176345]">{message}</div>}<div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_0.9fr]"><section className="card p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Recent student work</h2><p className="mt-1 text-sm text-[#6c8589]">Open a contribution to review it.</p></div><button className="text-sm font-bold text-[#087f78]" onClick={() => navigate('/students')}>View students</button></div><div className="mt-5 space-y-3">{items.length ? items.slice(0, 8).map((item) => <div key={item.id} className="flex w-full items-center justify-between gap-2 rounded-xl border border-[#e5efec] p-4 text-left transition hover:border-[#9ad7c5]"><button onClick={() => setSelected(item)} className="flex min-w-0 flex-1 items-center justify-between text-left"><div className="min-w-0"><p className="truncate text-sm font-bold">{item.title}</p><p className="mt-1 text-xs text-[#8ca1a3]">{item.profiles?.full_name || 'Student'} · {formatDate(item.contribution_date)}</p></div><StatusPill status={item.status} /></button>{(() => { const all = rowReviews[item.id] || []; const mine = all.filter((r) => r.teacher_id === profile.id); const canDelete = profile.role === 'admin' ? all.length > 0 : mine.length > 0; return canDelete ? <button title={profile.role === 'admin' ? `Delete ${all.length} review(s)` : 'Delete my review'} onClick={() => void removeMyReviewForRow(item.id)} className="shrink-0 rounded-lg p-2 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button> : null; })()}</div>) : <EmptyState icon={Code2} title="No student work yet" text="New contributions will appear here." />}</div></section><section className="card p-6"><h2 className="text-lg font-bold">Students needing attention</h2><p className="mt-1 text-sm text-[#6c8589]">Students with work waiting for review</p>{pending.length ? <div className="mt-5 space-y-3">{pending.slice(0, 5).map((item) => <button key={item.id} onClick={() => setSelected(item)} className="flex w-full items-center gap-3 rounded-xl bg-[#fff9ed] p-3 text-left"><Avatar profile={item.profiles || students.find((s) => s.id === item.student_id) || { id: '', full_name: 'Student', username: '', avatar: null, bio: '', github_url: null, linkedin_url: null, role: 'student' }} size="sm" /><div className="min-w-0"><p className="truncate text-sm font-semibold">{item.profiles?.full_name || 'Student'}</p><p className="truncate text-xs text-[#8ca1a3]">{item.title}</p></div></button>)}</div> : <p className="mt-6 text-sm text-[#6c8589]">Everything is reviewed. Nice work.</p>}</section></div>{selected && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#061c2c]/60 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6"><div className="flex items-start justify-between"><div><p className="eyebrow">Review contribution</p><h2 className="mt-2 text-2xl font-bold">{selected.title}</h2><p className="mt-1 text-sm text-[#6c8589]">{selected.profiles?.full_name || 'Student'} · {selected.subjects?.name}</p></div><button onClick={() => setSelected(null)} className="rounded-lg p-2 hover:bg-[#f2f8f6]"><X className="h-5 w-5" /></button></div><div className="mt-6 rounded-xl bg-[#f5faf8] p-4"><p className="text-sm font-bold">Summary</p><p className="mt-2 text-sm leading-6 text-[#536e74]">{selected.summary}</p>{selected.description && <><p className="mt-4 text-sm font-bold">Description</p><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[#536e74]">{selected.description}</p></>}{selected.code && <CodeBlock code={selected.code} compact />}<ReviewReferences contributionId={selected.id} githubUrl={selected.github_url} /></div>{selectedReviews.length > 0 && <div className="mt-4 border-t border-[#e5efec] pt-4"><p className="text-sm font-bold">Reviews given</p><div className="mt-3 space-y-2">{selectedReviews.map((r) => <div key={r.id} className="flex items-start justify-between gap-3 rounded-xl bg-white p-3"><div className="min-w-0"><p className="flex flex-wrap items-center gap-2 text-sm font-bold"><span className="truncate">{r.reviewer_name || 'Reviewer'}</span><RoleBadge role={r.reviewer_role} /></p><p className="mt-1 text-sm leading-5 text-[#536e74]">{r.feedback}</p></div><div className="flex shrink-0 items-center gap-2"><span className="text-sm font-bold text-[#087f78]">{r.score}%</span>{(profile.role === 'admin' || r.teacher_id === profile.id) && <button title="Delete this review" onClick={() => void removeReview(r.id)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div></div>)}</div></div>}<form onSubmit={submitReview} className="mt-6 space-y-4"><textarea className="field min-h-28" placeholder="Write constructive feedback" value={review.feedback} onChange={(e) => setReview({ ...review, feedback: e.target.value })} /><div className="grid gap-4 sm:grid-cols-2"><input className="field" type="number" min="0" max="100" placeholder="Score" value={review.score} onChange={(e) => setReview({ ...review, score: e.target.value })} /><select className="field" value={review.status} onChange={(e) => setReview({ ...review, status: e.target.value as 'approved' | 'needs_improvement' })}><option value="approved">Approve contribution</option><option value="needs_improvement">Needs improvement</option></select></div><button className="btn-primary w-full">Save review</button></form></div></div>}<NotesSection profile={profile} /></>; }

function AdminDashboard({ profile, navigate }: { profile: Profile; navigate: (path: string) => void }): JSX.Element {
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [noteFeedback, setNoteFeedback] = useState<(NoteFeedbackItem & { admin_notes?: { title: string } | null })[]>([]);
  const [people, setPeople] = useState<Profile[]>([]);
  const [to, setTo] = useState(''); const [nTitle, setNTitle] = useState(''); const [nMsg, setNMsg] = useState(''); const [nBusy, setNBusy] = useState(false); const [nNotice, setNNotice] = useState('');
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [pending, setPending] = useState<Contribution[]>([]);
  const [teacherContribs, setTeacherContribs] = useState<Contribution[]>([]);
  const [selected, setSelected] = useState<Contribution | null>(null);
  const [selectedReviews, setSelectedReviews] = useState<Feedback[]>([]);
  const [editing, setEditing] = useState<Contribution | null>(null);
  const [editValues, setEditValues] = useState({ title: '', summary: '', description: '', code: '', github_url: '' });
  const deleteContribution = async (id: string): Promise<void> => {
    if (!window.confirm('Delete this contribution permanently? This cannot be undone.')) return;
    await supabase.from('contribution_files').delete().eq('contribution_id', id);
    await supabase.from('feedback').delete().eq('contribution_id', id);
    const { error } = await supabase.from('contributions').delete().eq('id', id);
    setMessage(error ? friendlyError() : 'Contribution deleted.');
    if (!error) await load();
  };
  const openEdit = (item: Contribution): void => {
    setEditValues({ title: item.title, summary: item.summary || '', description: item.description || '', code: item.code || '', github_url: item.github_url || '' });
    setEditing(item);
  };
  const saveEdit = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (!editing) return;
    setBusy(true);
    const { error } = await supabase.from('contributions').update({ title: editValues.title, summary: editValues.summary, description: editValues.description || null, code: editValues.code || null, github_url: editValues.github_url || null }).eq('id', editing.id);
    setMessage(error ? friendlyError() : 'Contribution updated.');
    setBusy(false);
    if (!error) { setEditing(null); await load(); }
  };
  const [review, setReview] = useState({ feedback: '', score: '80', status: 'approved' as 'approved' | 'needs_improvement' });
  const [newSubject, setNewSubject] = useState('');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const load = async (): Promise<void> => {
    const [p, s, c, nf] = await Promise.all([
      supabase.from('profiles').select('*').order('created_at', { ascending: false }),
      supabase.from('subjects').select('*').order('name'),
      supabase.from('contributions').select('*, subjects(*), profiles(*)').order('created_at', { ascending: false }),
      supabase.from('note_feedback').select('*, admin_notes(title), profiles(role)').order('created_at', { ascending: false }).limit(6)
    ]);
    setProfiles((p.data || []) as Profile[]);
    setSubjects((s.data || []) as Subject[]);
    setPending((c.data || []).filter((item: Contribution) => item.status === 'pending') as Contribution[]);
    setTeacherContribs((c.data || []).filter((item: Contribution) => item.profiles?.role === 'teacher') as Contribution[]);
    setNoteFeedback((nf.data || []) as (NoteFeedbackItem & { admin_notes?: { title: string } | null })[]);
    setPeople((p.data || []).filter((x: Profile) => x.id !== profile.id) as Profile[]);
  };
  useEffect(() => { void load(); }, []);
  useLiveRefresh(() => void load());
  useEffect(() => { (async () => { if (!selected) { setSelectedReviews([]); return; } const r = await supabase.from('feedback').select('*').eq('contribution_id', selected.id).order('created_at', { ascending: false }); setSelectedReviews((r.data || []) as Feedback[]); })(); }, [selected]);
  const removeReview = async (id: string): Promise<void> => {
    if (!window.confirm('Delete this review? The student will no longer see this feedback.')) return;
    const { error } = await supabase.from('feedback').delete().eq('id', id);
    if (error) setMessage(friendlyError()); else { setMessage('Review deleted.'); setSelectedReviews((rows) => rows.filter((r) => r.id !== id)); if (selected) await syncContributionReviewState(selected.id); }
    await load();
  };
  const sendNotification = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (!to || !nTitle.trim() || !nMsg.trim()) { setNNotice('Choose a recipient and fill in both fields.'); return; }
    setNBusy(true); setNNotice('');
    const { error } = await supabase.from('notifications').insert({ user_id: to, title: nTitle.trim(), message: nMsg.trim(), type: 'message' });
    setNBusy(false);
    if (error) { setNNotice(friendlyError()); return; }
    setNTitle(''); setNMsg('');
    setNNotice('Notification sent.');
  };
  const changeRole = async (id: string, role: Role): Promise<void> => {
    const { error } = await supabase.rpc('set_profile_role', { p_profile_id: id, p_role: role });
    setMessage(error ? friendlyError() : 'Role updated.');
    if (!error) await load();
  };
  const deleteUser = async (user: Profile): Promise<void> => {
    if (!window.confirm(`Delete ${user.full_name || 'this user'} permanently? All of their contributions, feedback and notes will be removed. This cannot be undone.`)) return;
    const { data } = await supabase.rpc('delete_user', { p_user_id: user.id });
    const failed = (data as { error?: { message?: string } } | null)?.error?.message;
    setMessage(failed ? failed : `${user.full_name || 'User'} deleted.`);
    if (!failed) await load();
  };
  const addSubject = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (!newSubject.trim()) return;
    const { error } = await supabase.from('subjects').insert({ name: newSubject.trim() });
    setMessage(error ? 'That subject already exists or could not be added.' : 'Subject added.');
    setNewSubject('');
    if (!error) await load();
  };
  const submitReview = async (event: FormEvent): Promise<void> => {
    event.preventDefault();
    if (!selected || !review.feedback) { setMessage('Add feedback before saving the review.'); return; }
    const score = Number(review.score);
    if (score < 0 || score > 100) { setMessage('Score must be between 0 and 100.'); return; }
    setBusy(true);
    const { error: fbError } = await supabase.from('feedback').insert({ contribution_id: selected.id, teacher_id: profile.id, reviewer_name: profile.full_name || 'Administrator', reviewer_role: 'admin', feedback: review.feedback, score, status: review.status });
    if (fbError) { setMessage(friendlyError()); setBusy(false); return; }
    const { error: cError } = await supabase.from('contributions').update({ score, status: review.status }).eq('id', selected.id);
    if (cError) { setMessage(friendlyError()); setBusy(false); return; }
    await supabase.from('notifications').insert({ user_id: selected.student_id, title: review.status === 'approved' ? 'Contribution approved' : 'Feedback on your contribution', message: review.feedback, type: review.status });
    setMessage('Review saved and the student has been notified.');
    setSelected(null);
    setReview({ feedback: '', score: '80', status: 'approved' });
    setBusy(false);
    await load();
  };
  return <><PageHeader eyebrow="Platform control" title="Admin overview" description={`Signed in as ${profile.full_name || 'administrator'}. Manage access, curriculum, scoring, and the audit trail.`} action={<span className="inline-flex items-center gap-2 rounded-xl bg-[#e7f7f1] px-3 py-2 text-xs font-bold text-[#087f78]"><ShieldCheck className="h-4 w-4" />Admin access</span>} />{message && <div className="mb-6 rounded-xl bg-[#effbf5] px-4 py-3 text-sm text-[#176345]">{message}</div>}<div className="grid grid-cols-2 gap-3 sm:gap-4 xl:grid-cols-4"><StatCard label="Users" value={String(profiles.length)} detail="All platform profiles" icon={Users} onClick={() => navigate('/students')} title="Open student directory" /><StatCard label="Students" value={String(profiles.filter((p) => p.role === 'student').length)} detail="Learner accounts" icon={GraduationCap} onClick={() => navigate('/students')} title="Open student directory" /><StatCard label="Pending reviews" value={String(pending.length)} detail="Waiting for approval" icon={ListChecks} onClick={() => document.getElementById('approval-queue')?.scrollIntoView({ behavior: 'smooth' })} title="Jump to approval queue" /><StatCard label="Subjects" value={String(subjects.length)} detail="Learning areas" icon={BookOpen} onClick={() => document.getElementById('subjects-panel')?.scrollIntoView({ behavior: 'smooth' })} title="Jump to subjects" /></div>
  <section className="card mt-6 p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#e7f7f1] p-2.5 text-[#087f78]"><Mail className="h-5 w-5" /></div><div><h2 className="text-lg font-bold">Feedback on your notes</h2><p className="mt-0.5 text-sm text-[#6c8589]">What students and teachers are saying about the notes you published.</p></div></div>{noteFeedback.length ? <div className="mt-5 space-y-3">{noteFeedback.map((f) => <div key={f.id} className="rounded-xl bg-[#f6faf8] p-4"><div className="flex flex-wrap items-center justify-between gap-2"><span className="flex min-w-0 flex-wrap items-center gap-2"><span className="truncate text-sm font-bold text-[#185464]">{f.reviewer_name}</span><RoleBadge role={f.role || f.profiles?.role} /></span><span className="shrink-0 text-xs text-[#8ca1a3]">on “{f.admin_notes?.title || 'a note'}” · {formatDate(f.created_at.slice(0, 10))}</span></div><p className="mt-2 text-sm leading-6 text-[#536e74]">{f.feedback}</p><button className="mt-3 text-xs font-bold text-[#087f78] hover:underline" onClick={() => navigate(`/admin-notes/${f.note_id}`)}>Open note →</button></div>)}</div> : <p className="mt-5 text-sm text-[#6c8589]">No note feedback yet. Comments from students and teachers will appear here.</p>}</section>
  <section className="card mt-6 p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#ede9fe] p-2.5 text-[#6d5ae0]"><Megaphone className="h-5 w-5" /></div><div><h2 className="text-lg font-bold">Send a notification</h2><p className="mt-0.5 text-sm text-[#6c8589]">Message any teacher or student directly — it lands in their notifications instantly.</p></div></div>{nNotice && <p className="mt-3 text-sm text-[#176345]">{nNotice}</p>}<form onSubmit={sendNotification} className="mt-4 grid gap-3 sm:grid-cols-[1fr_1.2fr_1.4fr_auto]"><select className="field" value={to} onChange={(e) => setTo(e.target.value)}><option value="">Choose recipient…</option>{people.map((p) => <option key={p.id} value={p.id}>{p.full_name || p.username} · {p.role}</option>)}</select><input className="field" placeholder="Title" value={nTitle} onChange={(e) => setNTitle(e.target.value)} /><input className="field" placeholder="Message" value={nMsg} onChange={(e) => setNMsg(e.target.value)} /><button className="btn-primary inline-flex items-center justify-center gap-2" disabled={nBusy}>{nBusy ? 'Sending…' : <><Send className="h-4 w-4" />Send</>}</button></form></section>
  <section id="approval-queue" className="card mt-6 p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Approval queue</h2><p className="mt-1 text-sm text-[#6c8589]">Contributions waiting for admin review.</p></div></div>{pending.length ? <div className="mt-5 space-y-3">{pending.map((item) => <div key={item.id} className="flex w-full items-center justify-between rounded-xl border border-[#e5efec] p-4 text-left transition hover:border-[#9ad7c5] hover:bg-[#f6fcf9]"><button onClick={() => setSelected(item)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><div className="min-w-0"><p className="truncate text-sm font-bold text-[#185464]">{item.title}</p><p className="mt-1 text-xs text-[#8ca1a3]">{item.profiles?.full_name || 'Student'} · {item.subjects?.name || 'Uncategorized'} · {formatDate(item.contribution_date)}</p></div><StatusPill status={item.status} /></button><div className="ml-3 flex shrink-0 items-center gap-1"><button title="Edit contribution content" onClick={() => openEdit(item)} className="rounded-lg p-2 text-[#6c8589] transition hover:bg-[#e7f7f1] hover:text-[#087f78]"><PencilLine className="h-4 w-4" /></button><button title="Delete contribution" onClick={() => void deleteContribution(item.id)} className="rounded-lg p-2 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button></div></div>)} </div> : <div className="mt-5"><EmptyState icon={Check} title="All caught up" text="No contributions are waiting for approval right now." /></div>}</section>
  <section className="card mt-6 p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Teacher contributions</h2><p className="mt-1 text-sm text-[#6c8589]">Work published by teachers — visible to students and admins without approval.</p></div></div>{teacherContribs.length ? <div className="mt-5 space-y-3">{teacherContribs.map((item) => <div key={item.id} className="flex w-full items-center justify-between rounded-xl border border-[#e5efec] p-4 text-left transition hover:border-[#9ad7c5] hover:bg-[#f6fcf9]"><button onClick={() => navigate(`/contributions/${item.id}`)} className="flex min-w-0 flex-1 items-center gap-3 text-left"><div className="min-w-0"><p className="truncate text-sm font-bold text-[#185464]">{item.title}</p><p className="mt-1 text-xs text-[#8ca1a3]">{item.profiles?.full_name || 'Teacher'} · {item.subjects?.name || 'Uncategorized'} · {formatDate(item.contribution_date)}</p></div><StatusPill status={item.status} /></button><div className="ml-3 flex shrink-0 items-center gap-1"><button title="View contribution" onClick={() => navigate(`/contributions/${item.id}`)} className="rounded-lg p-2 text-[#6c8589] transition hover:bg-[#e7f7f1] hover:text-[#087f78]"><Eye className="h-4 w-4" /></button><button title="Delete contribution" onClick={() => void deleteContribution(item.id)} className="rounded-lg p-2 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button></div></div>)} </div> : <div className="mt-5"><EmptyState icon={BookOpen} title="No teacher contributions yet" text="When teachers publish work, it will appear here for everyone." /></div>}</section>
  <AdminNotesBoard navigate={navigate} profile={profile} />
  <div className="mt-6 grid gap-6 xl:grid-cols-[1.25fr_0.75fr]"><section className="card p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Users and roles</h2><p className="mt-1 text-sm text-[#6c8589]">Role changes are recorded securely.</p></div></div><div className="mt-5 space-y-3">{profiles.map((user) => <div key={user.id} className="flex flex-col gap-3 rounded-xl border border-[#e5efec] p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><Avatar profile={user} size="sm" /><div><p className="text-sm font-bold">{user.full_name || 'Unnamed user'}</p><p className="text-xs text-[#8ca1a3]">{user.username || user.id.slice(0, 8)}</p></div></div><div className="flex items-center gap-2"><select className="field max-w-[160px] py-2 text-xs" value={user.role} onChange={(e) => void changeRole(user.id, e.target.value as Role)}><option value="student">Student</option><option value="teacher">Teacher</option><option value="admin">Admin</option></select>{user.role !== 'admin' && user.id !== profile.id && <button title="Delete user" onClick={() => void deleteUser(user)} className="rounded-lg p-2 text-[#b05e5e] transition hover:bg-[#fbeeee] hover:text-[#a03333]"><Trash2 className="h-4 w-4" /></button>}</div></div>)}</div></section><div className="space-y-6"><section id="subjects-panel" className="card p-6"><h2 className="text-lg font-bold">Subjects</h2><form onSubmit={addSubject} className="mt-4 flex gap-2"><input className="field" placeholder="New subject" value={newSubject} onChange={(e) => setNewSubject(e.target.value)} /><button className="btn-primary px-3"><Plus className="h-4 w-4" /></button></form><div className="mt-4 flex flex-wrap gap-2">{subjects.map((subject) => <span key={subject.id} className="rounded-full bg-[#edf7f4] px-3 py-1.5 text-xs font-semibold text-[#087f78]">{subject.name}</span>)}</div></section><AdminNotesSection profile={profile} subjects={subjects} /></div></div>
  {editing && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#061c2c]/60 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6"><div className="flex items-start justify-between"><div><p className="eyebrow">Modify contribution</p><h2 className="mt-2 text-2xl font-bold">Edit content</h2><p className="mt-1 text-sm text-[#6c8589]">{editing.profiles?.full_name || 'Student'} · {editing.subjects?.name}</p></div><button onClick={() => setEditing(null)} className="rounded-lg p-2 hover:bg-[#f2f8f6]"><X className="h-5 w-5" /></button></div><form onSubmit={saveEdit} className="mt-6 space-y-4"><input className="field" placeholder="Title" value={editValues.title} onChange={(e) => setEditValues({ ...editValues, title: e.target.value })} /><textarea className="field min-h-20" placeholder="Summary" value={editValues.summary} onChange={(e) => setEditValues({ ...editValues, summary: e.target.value })} /><textarea className="field min-h-28" placeholder="Description" value={editValues.description} onChange={(e) => setEditValues({ ...editValues, description: e.target.value })} /><textarea className="field min-h-32 font-mono text-xs" placeholder="Code or notes" value={editValues.code} onChange={(e) => setEditValues({ ...editValues, code: e.target.value })} /><input className="field" type="url" placeholder="GitHub URL" value={editValues.github_url} onChange={(e) => setEditValues({ ...editValues, github_url: e.target.value })} /><button className="btn-primary w-full" disabled={busy || !editValues.title || !editValues.summary}>{busy ? 'Saving…' : 'Save changes'}</button></form></div></div>}
  {selected && <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#061c2c]/60 p-4"><div className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl bg-white p-6"><div className="flex items-start justify-between"><div><p className="eyebrow">Review contribution</p><h2 className="mt-2 text-2xl font-bold">{selected.title}</h2><p className="mt-1 text-sm text-[#6c8589]">{selected.profiles?.full_name || 'Student'} · {selected.subjects?.name}</p></div><button onClick={() => setSelected(null)} className="rounded-lg p-2 hover:bg-[#f2f8f6]"><X className="h-5 w-5" /></button></div><div className="mt-6 rounded-xl bg-[#f5faf8] p-4"><p className="text-sm font-bold">Summary</p><p className="mt-2 text-sm leading-6 text-[#536e74]">{selected.summary}</p>{selected.description && <><p className="mt-4 text-sm font-bold">Description</p><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-[#536e74]">{selected.description}</p></>}{selected.code && <CodeBlock code={selected.code} compact />}<ReviewReferences contributionId={selected.id} githubUrl={selected.github_url} /></div>{selectedReviews.length > 0 && <div className="mt-4 border-t border-[#e5efec] pt-4"><p className="text-sm font-bold">Reviews given</p><div className="mt-3 space-y-2">{selectedReviews.map((r) => <div key={r.id} className="flex items-start justify-between gap-3 rounded-xl bg-white p-3"><div className="min-w-0"><p className="flex flex-wrap items-center gap-2 text-sm font-bold"><span className="truncate">{r.reviewer_name || 'Reviewer'}</span><RoleBadge role={r.reviewer_role} /></p><p className="mt-1 text-sm leading-5 text-[#536e74]">{r.feedback}</p></div><div className="flex shrink-0 items-center gap-2"><span className="text-sm font-bold text-[#087f78]">{r.score}%</span>{(profile.role === 'admin' || r.teacher_id === profile.id) && <button title="Delete this review" onClick={() => void removeReview(r.id)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div></div>)}</div></div>}<form onSubmit={submitReview} className="mt-6 space-y-4"><textarea className="field min-h-28" placeholder="Write constructive feedback" value={review.feedback} onChange={(e) => setReview({ ...review, feedback: e.target.value })} /><div className="grid gap-4 sm:grid-cols-2"><input className="field" type="number" min="0" max="100" placeholder="Score" value={review.score} onChange={(e) => setReview({ ...review, score: e.target.value })} /><select className="field" value={review.status} onChange={(e) => setReview({ ...review, status: e.target.value as 'approved' | 'needs_improvement' })}><option value="approved">Approve contribution</option><option value="needs_improvement">Needs improvement</option></select></div><button className="btn-primary w-full" disabled={busy}>{busy ? 'Saving…' : 'Save review'}</button></form></div></div>}
  </>;
}
function NotFound({ navigate }: { navigate: (path: string) => void }): JSX.Element { return <div className="card mx-auto max-w-lg p-10 text-center"><h1 className="text-2xl font-bold">Page not found</h1><p className="mt-3 text-sm text-[#6c8589]">That workspace page does not exist.</p><button className="btn-primary mt-6" onClick={() => navigate('/dashboard')}>Go to dashboard</button></div>; }

// ---- Admin learning notes: authored by admins, visible to every role, no approval. ----
interface AdminNote { id: string; author_id: string; subject_id: string | null; title: string; summary: string | null; description: string | null; code: string | null; file_path: string | null; file_name: string | null; file_type: string | null; created_at: string; subjects?: { name: string } | null; profiles?: { full_name: string } | null; }
interface NoteFeedbackItem { id: string; note_id: string; user_id: string; reviewer_name: string; role?: string | null; feedback: string; created_at: string; profiles?: { role: string } | null; }
function useAdminNotes(): { notes: AdminNote[]; reload: () => Promise<void> } {
  const [notes, setNotes] = useState<AdminNote[]>([]);
  const reload = async (): Promise<void> => { const { data } = await supabase.from('admin_notes').select('*, subjects(name), profiles(full_name)').order('created_at', { ascending: false }); setNotes((data || []) as AdminNote[]); };
  useEffect(() => { void reload(); }, []);
  return { notes, reload };
}
function AdminNotesSection({ profile, subjects }: { profile: Profile; subjects: Subject[] }): JSX.Element {
  const { notes, reload } = useAdminNotes();
  const [subjectId, setSubjectId] = useState('');
  const [values, setValues] = useState({ title: '', summary: '', description: '', code: '' });
  const [file, setFile] = useState<File | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const submit = async (event: FormEvent): Promise<void> => {
    event.preventDefault(); setMessage('');
    if (!values.title.trim() || !values.summary.trim()) { setMessage('Add a title and a summary.'); return; }
    setBusy(true);
    let filePath: string | null = null; let fileName: string | null = null; let fileType: string | null = null;
    if (file) {
      const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, '-');
      const path = `admin-notes/${profile.id}/${Date.now()}-${safeName}`;
      const upload = await supabase.storage.from('study-notes').upload(path, file, { contentType: file.type || 'application/octet-stream', upsert: false });
      if (upload.error) { setMessage('The file could not be uploaded. Please try again.'); setBusy(false); return; }
      filePath = path; fileName = file.name; fileType = file.type || 'application/octet-stream';
    }
    const { error } = await supabase.from('admin_notes').insert({ subject_id: subjectId || null, title: values.title.trim(), summary: values.summary.trim(), description: values.description.trim() || null, code: values.code.trim() || null, file_path: filePath, file_name: fileName, file_type: fileType });
    if (error) { setMessage(friendlyError()); setBusy(false); return; }
    setValues({ title: '', summary: '', description: '', code: '' }); setFile(null); setSubjectId('');
    setMessage('Admin note published. It is visible to every student and teacher now.');
    setBusy(false); await reload();
  };
  const remove = async (id: string): Promise<void> => {
    if (!window.confirm('Delete this admin note?')) return;
    await supabase.from('admin_notes').delete().eq('id', id);
    await reload();
  };
  return <section className="card p-6"><h2 className="text-lg font-bold">Learning notes for everyone</h2><p className="mt-1 text-sm text-[#6c8589]">Publish notes to all students and teachers — no approval needed.</p><form onSubmit={submit} className="mt-4 space-y-3"><select className="field" value={subjectId} onChange={(e) => setSubjectId(e.target.value)}><option value="">Choose a subject (optional)</option>{subjects.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select><input className="field" placeholder="Note title" value={values.title} onChange={(e) => setValues({ ...values, title: e.target.value })} /><textarea className="field min-h-16" placeholder="Summary — one or two lines" value={values.summary} onChange={(e) => setValues({ ...values, summary: e.target.value })} /><textarea className="field min-h-24" placeholder="Full description" value={values.description} onChange={(e) => setValues({ ...values, description: e.target.value })} /><textarea className="field min-h-28 font-mono text-xs" placeholder="Code example (optional)" value={values.code} onChange={(e) => setValues({ ...values, code: e.target.value })} /><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-[#aad9ca] bg-[#f5fcf9] p-3"><Upload className="h-4 w-4 text-[#087f78]" /><span className="min-w-0 truncate text-xs font-semibold text-[#185464]">{file ? file.name : 'Attach a PDF or image (optional)'}</span><input className="hidden" type="file" accept="application/pdf,image/*" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label>{message && <p className="text-xs text-[#176345]">{message}</p>}<button className="btn-primary w-full" disabled={busy}>{busy ? 'Publishing…' : 'Publish note'}</button></form>{notes.length > 0 && <div className="mt-5 space-y-2 border-t border-[#e5efec] pt-4"><p className="text-xs font-bold uppercase tracking-wide text-[#8ca1a3]">Published notes ({notes.length})</p>{notes.slice(0, 5).map((note) => <div key={note.id} className="flex items-center justify-between gap-2 rounded-lg bg-[#f6faf8] px-3 py-2"><span className="min-w-0 truncate text-xs font-semibold text-[#185464]">{note.title}{note.subjects ? ` · ${note.subjects.name}` : ''}</span><button title="Delete note" onClick={() => void remove(note.id)} className="shrink-0 rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-3.5 w-3.5" /></button></div>)}</div>}</section>;
}
function AdminNotesBoard({ navigate, profile }: { navigate: (path: string) => void; profile?: Profile }): JSX.Element {
  const { notes, reload } = useAdminNotes();
  const removeNote = async (id: string): Promise<void> => {
    if (!window.confirm('Delete this note for everyone?')) return;
    const { error } = await supabase.from('admin_notes').delete().eq('id', id);
    if (!error) await reload();
  };
  if (!notes.length) return null as unknown as JSX.Element;
  return <section className="card mt-6 p-6"><div className="flex items-center gap-3"><div className="rounded-xl bg-[#e7f7f1] p-2 text-[#087f78]"><BookOpen className="h-5 w-5" /></div><div><p className="text-lg font-bold">Notes from the admin</p><p className="text-sm text-[#6c8589]">Learning references shared by platform administrators.</p></div></div><div className="mt-5 grid gap-3 md:grid-cols-2">{notes.slice(0, 4).map((note) => <div key={note.id} className="rounded-xl border border-[#e5efec] p-4"><div className="flex items-center justify-between gap-2"><span className="rounded-full bg-[#e7f7f1] px-2.5 py-1 text-[10px] font-bold text-[#087f78]">{note.subjects?.name || 'General'}</span><div className="flex items-center gap-1"><button title="Open this note" onClick={() => navigate(`/admin-notes/${note.id}`)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#e7f7f1] hover:text-[#087f78]"><Eye className="h-4 w-4" /></button>{profile?.role === 'admin' && <button title="Delete note" onClick={() => void removeNote(note.id)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div></div><h3 className="mt-2 truncate font-bold text-[#185464]">{note.title}</h3>{note.summary && <p className="mt-1 line-clamp-2 text-xs leading-5 text-[#6c8589]">{note.summary}</p>}</div>)}</div>{notes.length > 4 && <p className="mt-3 text-xs text-[#8ca1a3]">{notes.length - 4} more on the learning path page.</p>}</section>;
}
function AdminNoteDetail({ navigate, noteId, profile }: { navigate: (path: string) => void; noteId: string; profile: Profile }): JSX.Element {
  const [note, setNote] = useState<AdminNote | null>(null);
  const [comments, setComments] = useState<NoteFeedbackItem[]>([]);
  const [text, setText] = useState('');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const load = async (): Promise<void> => { const n = await supabase.from('admin_notes').select('*, subjects(name), profiles(full_name)').eq('id', noteId).maybeSingle(); const fb = await supabase.from('note_feedback').select('*, profiles(role)').eq('note_id', noteId).order('created_at', { ascending: true }); setNote((n.data as AdminNote) ?? null); setComments((fb.data || []) as NoteFeedbackItem[]); setLoading(false); };
  useEffect(() => { void load(); }, [noteId]);
  const submit = async (event: FormEvent): Promise<void> => { event.preventDefault(); if (!text.trim()) return; setBusy(true); setMessage(''); const { error } = await supabase.from('note_feedback').insert({ note_id: noteId, reviewer_name: profile.full_name || profile.username || 'Member', role: profile.role, feedback: text.trim() }); if (error) { setMessage(friendlyError()); setBusy(false); return; } setText(''); setBusy(false); await load(); };
  const removeComment = async (id: string): Promise<void> => { const { error } = await supabase.from('note_feedback').delete().eq('id', id); if (error) setMessage(friendlyError()); await load(); };
  if (loading) return <LoadingPanel />;
  if (!note) return <NotFound navigate={() => navigate('/dashboard')} />;
  return <><button className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-[#6c8589] hover:text-[#087f78]" onClick={() => navigate('/dashboard')}><ArrowLeft className="h-4 w-4" />Back</button><div className="mb-8"><div className="flex flex-wrap items-center gap-3"><span className="rounded-full bg-[#e7f7f1] px-2.5 py-1 text-[10px] font-bold text-[#087f78]">{note.subjects?.name || 'General'}</span><span className="text-sm text-[#8ca1a3]">By {note.profiles?.full_name || 'Administrator'} · {formatDate(note.created_at.slice(0, 10))}</span></div><h1 className="mt-3 text-4xl font-bold tracking-tight text-[#102a3a]">{note.title}</h1>{note.summary && <p className="mt-3 max-w-2xl text-base leading-7 text-[#61777c]">{note.summary}</p>}</div><div className="grid gap-6 lg:grid-cols-[1.3fr_0.7fr]"><section className="card p-6"><h2 className="text-lg font-bold">About this note</h2><p className="mt-4 whitespace-pre-wrap text-sm leading-7 text-[#536e74]">{note.description || 'No additional description.'}</p>{note.code && <CodeBlock code={note.code} />}</section><section className="card p-6"><h2 className="font-bold">Attachment</h2>{note.file_path ? <NoteFileLink bucket="study-notes" path={note.file_path} name={note.file_name || 'Download'} /> : <p className="mt-4 text-sm text-[#8ca1a3]">No file attached to this note.</p>}</section></div><section className="card mt-6 p-6"><h2 className="text-lg font-bold">Feedback on this note</h2><p className="mt-1 text-sm text-[#6c8589]">Questions and thoughts from students and teachers.</p>{message && <p className="mt-3 text-sm text-[#a33b3b]">{message}</p>}<form onSubmit={submit} className="mt-4 space-y-3"><textarea className="field min-h-20" placeholder="Share your feedback on this note…" value={text} onChange={(e) => setText(e.target.value)} /><button className="btn-primary" disabled={busy || !text.trim()}>{busy ? 'Posting…' : 'Post feedback'}</button></form><div className="mt-5 space-y-3">{comments.length ? comments.map((c) => <div key={c.id} className="rounded-xl bg-[#f6faf8] p-4"><div className="flex items-center justify-between gap-3"><span className="flex min-w-0 items-center gap-2"><span className="truncate text-sm font-bold text-[#185464]">{c.reviewer_name}</span><RoleBadge role={c.role || c.profiles?.role} /></span><div className="flex items-center gap-2"><span className="text-xs text-[#8ca1a3]">{formatDate(c.created_at.slice(0, 10))}</span>{(c.user_id === profile.id || profile.role === 'admin') && <button title="Delete comment" onClick={() => void removeComment(c.id)} className="rounded-lg p-1.5 text-[#6c8589] transition hover:bg-[#fff4f4] hover:text-[#a33b3b]"><Trash2 className="h-4 w-4" /></button>}</div></div><p className="mt-2 text-sm leading-6 text-[#536e74]">{c.feedback}</p></div>) : <p className="text-sm text-[#8ca1a3]">No feedback yet. Be the first to share your thoughts.</p>}</div></section></>;
}
function NoteFileLink({ bucket, path, name }: { bucket: string; path: string; name: string }): JSX.Element { const [url, setUrl] = useState(''); useEffect(() => { (async () => { const result = await supabase.storage.from(bucket).createSignedUrl(path, 3600); setUrl(result.data?.signedUrl || ''); })(); }, [bucket, path]); return url ? <a href={url} target="_blank" rel="noreferrer" className="mt-4 flex items-center gap-3 rounded-xl bg-[#f5faf8] p-3 text-sm font-semibold text-[#087f78] hover:bg-[#e7f7f1]"><FileText className="h-4 w-4" />{name}</a> : <p className="mt-4 text-sm text-[#8ca1a3]">Preparing file…</p>; }

export default App;
